import { PersonaEra, PersonaTerm } from './types';

type PersonaSeed = {
  id: string;
  name: string;
  nameEn: string;
  group: string;
  groupEn: string;
  def: string;
  defEn: string;
  ontologyLevel?: 1 | 2 | 3 | 4 | 5;
  eras?: PersonaEra[];
  risk?: 'clean' | 'medium' | 'high';
  tags?: string[];
  styleTags?: string[];
  controls?: string[];
  forbids?: string[];
  absorptionRule?: string;
  absorptionRuleEn?: string;
};

const baseControls = ['costume', 'prop', 'wear_trace', 'pose', 'symbol', 'hair', 'makeup'];
const defaultForbids = ['宫廷礼制过度覆盖', '无解释高魔法器官', '随机战术装备堆叠', '纯白摄影棚贵族化'];
const modernEras: PersonaEra[] = ['modern', 'contemporary', 'timeless'];
const contemporaryEras: PersonaEra[] = ['contemporary', 'near_future', 'timeless'];
const industrialModernEras: PersonaEra[] = ['industrial', 'modern', 'contemporary', 'timeless'];

const sp = (seed: PersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 1;
  const eras = seed.eras ?? modernEras;
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'medium' : 'clean');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  return {
    id: `cd_persona_street_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '街头 / 亚文化 / 青年部落',
    personaCategoryEn: 'Street / Subculture / Youth Tribe',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的穿搭制度、社群标记、道具、姿态、街区位置或消费痕迹，不要直接变成无关职业或怪物器官。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the outfit system, group marks, props, posture, street position, or consumption traces of "${seed.nameEn}"; do not turn them into unrelated jobs or monster organs.`,
    tags: Array.from(new Set(['persona', 'street', 'subculture', 'compound_persona', ...(seed.tags || [])])),
    realityTags: ontologyLevel <= 1 ? ['realist_safe'] : ontologyLevel <= 3 ? ['stylized_boundary'] : ['nonreal_ontology'],
    styleTags: Array.from(new Set(['street', 'subculture', ...(seed.styleTags || []), ...(seed.tags || [])])),
    timeTags: eras
  };
};

const seeds: PersonaSeed[] = [
  { id: 'nineties_gangsta_rapper', name: '90年代匪帮说唱歌手', nameEn: '1990s Gangsta Rapper', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是90年代街区影像里的强硬说唱身体。造型入口：90年代街区影像里的强硬说唱身体。母题：把街区威慑和音乐身份穿成公共形象的人。张力：表演性的压迫感与真实街头防御姿态并存。视觉证据：宽大球衣、金链、棒球帽、硬挺下巴、低角度站姿和少而重的手势。边界：避免写成持械黑帮或普通复古歌手。', defEn: 'First read: a hard rap body from 1990s block imagery. Styling entry: a hard rap body from 1990s block imagery. Motif: someone wearing neighborhood intimidation and music identity as a public image. Tension: between performative pressure and real street-defense posture. Visual evidence: oversized jersey, gold chain, cap, hard jaw, low-angle stance, and few heavy gestures. Boundary: avoid turn him into an armed gangster or generic retro singer.', tags: ['hiphop', 'gangsta_rap', '90s'], eras: ['modern', 'timeless'] },
  { id: 'east_coast_boom_bap_mc', name: '东海岸Boom Bap MC', nameEn: 'East-Coast Boom-Bap MC', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是地下录音室和砖墙街角之间的东海岸MC。造型入口：地下录音室和砖墙街角之间的东海岸MC。母题：用歌词、黑胶和城市冷硬感建立权威的说唱者。张力：低调穿着下仍有强烈节拍控制。视觉证据：连帽衫、厚靴、深色外套、压低帽檐、麦克风或黑胶包、前倾身体。边界：避免给明星光泽或舞台偶像化。', defEn: 'First read: an East-Coast MC between basement studio and brick corner. Styling entry: an East-Coast MC between basement studio and brick corner. Motif: a rapper building authority through lyrics, vinyl, and cold city texture. Tension: strong rhythm control beneath low-profile clothing. Visual evidence: hoodie, heavy boots, dark outerwear, lowered brim, mic or vinyl bag, and forward-leaning body. Boundary: avoid add celebrity gloss or idol-stage polish.', tags: ['boom_bap', 'east_coast', 'mc'] },
  { id: 'west_coast_lowrider_rapper', name: '西海岸低趴车说唱客', nameEn: 'West-Coast Lowrider Rapper', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是阳光街区和低趴车文化里的西海岸说唱客。造型入口：阳光街区和低趴车文化里的西海岸说唱客。母题：把松弛、炫耀和地方性危险混在一起的街头表演者。张力：身体看似慢，却始终在占据空间。视觉证据：格纹衬衫、白背心、墨镜、低裤线、放松肩膀、手腕金属反光和低速展示姿态。边界：避免写成普通海滩潮人。', defEn: 'First read: a West-Coast rapper inside sunny block and lowrider culture. Styling entry: a West-Coast rapper inside sunny block and lowrider culture. Motif: a street performer mixing ease, display, and local danger. Tension: the body looks slow while constantly claiming space. Visual evidence: plaid shirt, white tank, sunglasses, low pant line, relaxed shoulders, wrist metal, and slow-display posture. Boundary: avoid making him a generic beach streetwear figure.', tags: ['west_coast', 'lowrider', 'rap'] },
  { id: 'trap_rapper', name: 'Trap说唱歌手', nameEn: 'Trap Rapper', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是当代夜生活和手机镜头里的Trap说唱歌手。造型入口：当代夜生活和手机镜头里的Trap说唱歌手。母题：把创伤、财富和炫耀压缩成面部与珠宝的人。张力：服装很亮，身体却显得被夜晚和屏幕耗空。视觉证据：面部纹身、厚珠宝、设计师运动套装、疲惫眼神、懒散姿态和精准占画面的手势。边界：避免写成单纯富二代或危险罪犯。', defEn: 'First read: a trap rapper inside contemporary nightlife and phone-camera culture. Styling entry: a trap rapper inside contemporary nightlife and phone-camera culture. Motif: someone compressing pain, wealth, and flex into face and jewelry. Tension: the clothing shines while the body feels emptied by night and screens. Visual evidence: face tattoos, heavy jewelry, designer sportswear, tired eyes, lazy posture, and frame-claiming hands. Boundary: avoid making him merely a rich kid or dangerous criminal.', risk: 'medium', tags: ['trap', 'rapper', 'tattoo'] },
  { id: 'drill_crew_member', name: 'Drill街区成员', nameEn: 'Drill Crew Member', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是被黑色街区制服匿名化的Drill成员。造型入口：被黑色街区制服匿名化的Drill成员。母题：群体边界里的冷警戒信号。张力：他必须显得危险，但危险来自遮蔽、距离和短促动作，不来自武装装备。视觉证据：黑色羽绒、面罩、束紧帽檐、少量眼神露出、厚重肩部和群体间距。边界：避免写成战术士兵或具体犯罪角色。', defEn: 'First read: a Drill crew member anonymized by black block uniform. Styling entry: a Drill crew member anonymized by black block uniform. Motif: a cold warning signal inside group boundary. Tension: he must feel dangerous, but danger comes from concealment, distance, and clipped movement, not weapons. Visual evidence: black puffer, mask, tight brim, minimal eye exposure, heavy shoulders, and crew spacing. Boundary: avoid turn him into a tactical soldier or explicit crime character.', risk: 'medium', tags: ['drill', 'crew', 'mask'] },
  { id: 'old_school_bboy', name: '老派B-Boy', nameEn: 'Old-School B-Boy', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是80/90年代街舞场地里的老派B-Boy。造型入口：80/90年代街舞场地里的老派B-Boy。母题：把身体训练成节拍机器的舞者。张力：服装看似松弛，身体却极其精准、随时能落到地板。视觉证据：运动套装、头巾、护腕、磨亮运动鞋、膝肘使用痕迹和可旋转的重心。边界：避免写成普通运动男孩或现代舞台偶像。', defEn: 'First read: an old-school B-Boy from an 80s/90s street-dance spot. Styling entry: an old-school B-Boy from an 80s/90s street-dance spot. Motif: a dancer training the body into a rhythm machine. Tension: loose clothing over precise movement, always ready to drop to the floor. Visual evidence: tracksuit, bandana, wrist guards, polished sneakers, used elbows and knees, and a spin-ready center of gravity. Boundary: avoid making him a generic sporty boy or modern stage idol.', tags: ['bboy', 'breakdance', 'old_school'] },
  { id: 'hiphop_dance_girl', name: '嘻哈舞者女孩', nameEn: 'Hip-Hop Dance Girl', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是排练室和街区舞圈里的嘻哈舞者。造型入口：宽松裤、短上衣、排练汗水和肩颈节奏。母题：用身体控制节拍的年轻女性。张力：她可以性感，但性感必须来自动作能力而不是摆拍取悦。视觉证据：宽松裤、短上衣、扎紧头发、排练汗水、腰腹控制、膝盖弹性和肩颈节奏。边界：保持成人边界，避免偶像写真。', defEn: 'First read: a hip-hop dancer from rehearsal room and block dance circle. Styling entry: baggy pants, cropped top, rehearsal sweat, and shoulder-neck rhythm. Motif: a young woman controlling rhythm through the body. Tension: she can be attractive, but the appeal must come from movement skill rather than posing to please. Visual evidence: baggy pants, cropped top, tied hair, rehearsal sweat, waist control, elastic knees, and shoulder-neck rhythm. Boundary: keep adult boundaries and avoid idol pin-up.', tags: ['hiphop_dancer', 'girl', 'dance'] },
  { id: 'mixtape_hustler', name: '地下Mixtape贩卖者', nameEn: 'Underground Mixtape Hustler', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是把音乐、货物和自我介绍都挂在身上的地下Mixtape贩卖者。造型入口：把音乐、货物和自我介绍都挂在身上的地下Mixtape贩卖者。母题：街角自我发行的年轻推销者。张力：他既像艺术家，又不得不用销售姿态证明自己存在。视觉证据：背包、手递唱片、粗糙封面、旧耳机、半伸出的手和靠近陌生人的身体角度。边界：避免写成普通小贩或完整犯罪叙事。', defEn: 'First read: an underground mixtape hustler wearing music, stock, and self-introduction on the body. Styling entry: an underground mixtape hustler wearing music, stock, and self-introduction on the body. Motif: a corner self-distributor. Tension: he is an artist but must use sales posture to prove he exists. Visual evidence: backpack, hand-sold discs, rough covers, old headphones, half-extended hand, and a body leaning toward strangers. Boundary: avoid making him a generic vendor or full crime story.', tags: ['mixtape', 'hustler', 'underground'] },
  { id: 'freestyle_battle_mc', name: 'Freestyle Battle MC', nameEn: 'Freestyle Battle MC', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是正在把语言当作近身武器的Freestyle Battle MC。造型入口：正在把语言当作近身武器的Freestyle Battle MC。母题：街头语言决斗者。张力：服装可以很简单，但嘴、手和重心必须像随时要攻击。视觉证据：手持麦克风、前倾肩线、绷紧嘴角、挑衅眼神、脖颈张力和压迫性站位。边界：避免写成舞台主持或暴力打斗角色。', defEn: 'First read: a freestyle battle MC using language as a close-range weapon. Styling entry: a freestyle battle MC using language as a close-range weapon. Motif: a street verbal duelist. Tension: clothing may stay simple while mouth, hands, and weight feel ready to strike. Visual evidence: handheld mic, forward shoulders, tightened mouth corners, challenging eyes, neck tension, and pressuring stance. Boundary: avoid making him a stage host or physical fight character.', tags: ['freestyle', 'battle', 'mc'] },
  { id: 'luxury_hiphop_heir', name: '奢华嘻哈继承人', nameEn: 'Luxury Hip-Hop Heir', group: 'A. 嘻哈 / 说唱街区', groupEn: 'A. Hip-Hop / Rap Block', def: '第一识别是把街头符号穿成继承资产的奢华嘻哈继承人。造型入口：把街头符号穿成继承资产的奢华嘻哈继承人。母题：被家族资源保护过的年轻街头权力。张力：他借用嘻哈姿态，却没有真正的匮乏经验。视觉证据：高端运动装、钻饰、干净球鞋、过度松弛坐姿、被保护过的骄傲和昂贵材料维护感。边界：避免写成普通富人或真正街头苦难角色。', defEn: 'First read: a luxury hip-hop heir wearing street signs as inherited assets. Styling entry: a luxury hip-hop heir wearing street signs as inherited assets. Motif: young street power protected by family resources. Tension: he borrows hip-hop posture without carrying real scarcity. Visual evidence: luxury sportswear, diamonds, clean sneakers, over-relaxed seated pose, protected pride, and expensive material maintenance. Boundary: avoid making him generic rich or a real hardship street figure.', risk: 'medium', tags: ['luxury_hiphop', 'heir', 'party'] },

  { id: 'skate_park_local', name: '滑板场本地青年', nameEn: 'Local Skate-Park Kid', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是已经被滑板场认领的本地青年。造型入口：已经被滑板场认领的本地青年。母题：长期占据某个台阶、坡道和混凝土边缘的场地身体。张力：他看起来松散，却拥有摔过很多次后的精准平衡。视觉证据：磨损板面、破洞裤、旧帆布鞋、膝盖擦伤、放松到像占有台阶的站姿。边界：避免写成英雄动作或普通运动少年。', defEn: 'First read: a local kid already claimed by the skate park. Styling entry: a local kid already claimed by the skate park. Motif: a spot-body shaped by steps, ramps, and concrete edges over time. Tension: he looks loose but carries precise balance from many falls. Visual evidence: scraped deck, ripped pants, old canvas shoes, bruised knees, and a relaxed stance that seems to own the steps. Boundary: avoid making him a heroic action figure or generic sporty youth.', tags: ['skate', 'local', 'youth'] },
  { id: 'pro_skater_video_part', name: '录像带滑板明星', nameEn: 'Video-Part Skate Star', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是像刚从一段滑板录像里暂停下来的职业滑手。造型入口：像刚从一段滑板录像里暂停下来的职业滑手。母题：被广角镜头、品牌赞助和摔痕共同塑造的街头运动明星。张力：造型干净可推广，身体却保留真实使用痕迹。视觉证据：品牌T恤、宽裤、贴纸板、肩膝鞋底的动作余波和广角式身体张力。边界：避免写成摆拍潮人。', defEn: 'First read: a pro skater paused out of a video part. Styling entry: a pro skater paused out of a video part. Motif: a street-sport star shaped by fisheye camera, sponsorship, and fall marks. Tension: clean promotable styling over a body with real use traces. Visual evidence: brand tee, wide pants, stickered board, motion residue in shoulders/knees/soles, and fisheye-style body tension. Boundary: avoid making him a posed streetwear model.', tags: ['skate', 'video_part', 'brand'] },
  { id: 'girl_skate_crew_member', name: '女子滑板团成员', nameEn: 'Girl Skate Crew Member', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是女子滑板团里的成员，而不是甜美街拍女孩。造型入口：女子滑板团里的成员，而不是甜美街拍女孩。母题：用团体感和移动重心建立自信的街头女性。张力：她被镜头看见，却不为镜头调整成讨喜姿态。视觉证据：宽松短裤、贴纸滑板、松散扎发、轻微擦伤、移动中说话般的身体。边界：避免写成偶像化少女或可爱摆拍。', defEn: 'First read: a member of a girl skate crew, not a cute street-snap girl. Styling entry: a member of a girl skate crew, not a cute street-snap girl. Motif: a street woman building confidence through crew belonging and moving weight. Tension: she is seen by the camera but does not adjust into a pleasing pose. Visual evidence: loose shorts, stickered board, loosely tied hair, small scratches, and a body that speaks while moving. Boundary: avoid making her an idolized girl or cute pose model.', tags: ['girl_skate', 'crew', 'skate'] },
  { id: 'bmx_street_rider', name: 'BMX街头骑手', nameEn: 'BMX Street Rider', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是把车把、鞋尖和栏杆距离都算进身体里的BMX街头骑手。造型入口：把车把、鞋尖和栏杆距离都算进身体里的BMX街头骑手。母题：爆发前压缩的城市骑行身体。张力：他看似静止，却每个关节都准备弹起。视觉证据：小轮车、半指手套、链条油污、卷起裤脚、紧绷前臂和车把关系。边界：避免写成普通自行车通勤者。', defEn: 'First read: a BMX street rider whose body includes handlebar, toe, and rail distance. Styling entry: a BMX street rider whose body includes handlebar, toe, and rail distance. Motif: a compressed urban riding body before burst. Tension: he looks still while every joint is ready to pop. Visual evidence: BMX bike, fingerless gloves, chain grease, rolled cuffs, tense forearms, and clear handlebar relation. Boundary: avoid making him a regular bicycle commuter.', tags: ['bmx', 'street_rider', 'bike'] },
  { id: 'roller_derby_rebel', name: '轮滑叛逆女孩', nameEn: 'Roller Derby Rebel Girl', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是可爱外壳下带冲撞感的轮滑叛逆女孩。造型入口：可爱外壳下带冲撞感的轮滑叛逆女孩。母题：把竞技、挑衅和少女化符号混合的场地身体。张力：甜感必须被低重心和护具刮痕打断。视觉证据：轮滑鞋、护膝、撞色袜、短裙或短裤、前压肩膀和挑衅笑容。边界：避免写成单纯可爱轮滑写真。', defEn: 'First read: a roller-derby rebel girl whose cute shell carries impact. Styling entry: a roller-derby rebel girl whose cute shell carries impact. Motif: a rink body mixing sport, provocation, and girlish signs. Tension: sweetness must be interrupted by low center of gravity and scratched gear. Visual evidence: roller skates, knee pads, contrast socks, skirt or shorts, forward shoulders, and provocative smile. Boundary: avoid making her a purely cute roller-skate portrait.', tags: ['roller_derby', 'rebel', 'girl'] },
  { id: 'parkour_rooftop_runner', name: '跑酷屋顶青年', nameEn: 'Parkour Rooftop Runner', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是把城市边缘当作身体路线的跑酷屋顶青年。造型入口：把城市边缘当作身体路线的跑酷屋顶青年。母题：距离判断和轻量化装备训练出的城市身体。张力：他像要飞跃空间，却必须保持完全现实的重力感。视觉证据：轻便运动服、磨损掌心、紧贴身体的小包、预备跳跃的脚尖和测距眼神。边界：避免写成超级英雄或空中特技海报。', defEn: 'First read: a parkour rooftop runner treating urban edges as body routes. Styling entry: a parkour rooftop runner treating urban edges as body routes. Motif: an urban body trained by distance judgment and lightweight gear. Tension: he seems ready to cross space while remaining fully realistic under gravity. Visual evidence: light sportswear, worn palms, compact body-hugging bag, toes set for a jump, and distance-reading eyes. Boundary: avoid making him a superhero or aerial stunt poster.', tags: ['parkour', 'rooftop', 'runner'] },
  { id: 'streetball_showman', name: '街球表演者', nameEn: 'Streetball Showman', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是把篮球动作变成围观表演的街球玩家。造型入口：把篮球动作变成围观表演的街球玩家。母题：街区球场上的身体主持人。张力：他既在竞技，也在用手势和表情控制观众注意力。视觉证据：球场背心、护腕、宽松短裤、手指炫技、髋部节奏和把篮球当身体延伸的姿态。边界：避免写成职业联赛球员。', defEn: 'First read: a streetball player turning basketball movement into crowd performance. Styling entry: a streetball player turning basketball movement into crowd performance. Motif: a bodily host on a block court. Tension: he is both competing and controlling attention through gestures and face. Visual evidence: court jersey, wristbands, loose shorts, showy fingers, hip rhythm, and posture treating the ball as body extension. Boundary: avoid making him a professional league player.', tags: ['streetball', 'showman', 'court'] },
  { id: 'surf_skate_coastal_kid', name: '海岸滑板青年', nameEn: 'Coastal Surf-Skate Kid', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是把海浪平衡带到街道上的海岸滑板青年。造型入口：把海浪平衡带到街道上的海岸滑板青年。母题：介于冲浪和街道之间的横向身体。张力：他像度假般松弛，却由长期阳光、盐雾和板面训练塑形。视觉证据：晒痕、盐雾头发、宽松短裤、褪色T恤、冲浪滑板和横向摆动站姿。边界：避免写成普通海边游客。', defEn: 'First read: a coastal surf-skate kid bringing wave balance into the street. Styling entry: a coastal surf-skate kid bringing wave balance into the street. Motif: a lateral body between surfing and pavement. Tension: vacation-like ease shaped by long sun, salt, and board training. Visual evidence: sun marks, salt-stiff hair, loose shorts, faded tee, surf-skate board, and side-sway stance. Boundary: avoid making him a generic beach tourist.', tags: ['surf_skate', 'coastal', 'youth'] },
  { id: 'night_skate_courier', name: '夜滑快递青年', nameEn: 'Night-Skate Courier', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是把滑板变成夜间工作路线的快递青年。造型入口：把滑板变成夜间工作路线的快递青年。母题：速度、任务和街头移动合成的劳动身体。张力：滑手姿态被时间压力压成前倾。视觉证据：滑板、斜挎包、反光贴、紧袖外套、手机导航灯、被包带拉住的肩膀和赶路膝盖。边界：避免写成普通酷滑手。', defEn: 'First read: a night-skate courier turning the skateboard into a work route. Styling entry: a night-skate courier turning the skateboard into a work route. Motif: a labor body made from speed, task, and street movement. Tension: skater posture compressed forward by time pressure. Visual evidence: skateboard, sling bag, reflective tape, tight-sleeved jacket, phone navigation light, bag-pulled shoulders, and delivery knees. Boundary: avoid making him a generic cool skater.', tags: ['skate', 'courier', 'night'] },
  { id: 'concrete_plaza_lurker', name: '混凝土广场游荡者', nameEn: 'Concrete-Plaza Lurker', group: 'B. 滑板 / BMX / 街头运动', groupEn: 'B. Skate / BMX / Street Sport', def: '第一识别是长期待在混凝土广场边缘的游荡者。造型入口：长期待在混凝土广场边缘的游荡者。母题：场地里的背景常驻者。张力：他不像主角，却比任何临时来的人都更属于这里。视觉证据：旧夹克、耳机、台阶边缘坐姿、半拿半放的滑板、安静观察和随时能加入也能消失的身体状态。边界：避免写成阴郁流浪汉或剧情反派。', defEn: 'First read: a long-term lurker at the edge of a concrete plaza. Styling entry: a long-term lurker at the edge of a concrete plaza. Motif: the permanent background figure of a spot. Tension: he is not a protagonist, yet belongs here more than anyone passing through. Visual evidence: old jacket, headphones, step-edge seated posture, board half-held or half-dropped, quiet watching, and a body able to join or disappear. Boundary: avoid making him a gloomy homeless figure or plot villain.', tags: ['plaza', 'lurker', 'street'] },

  { id: 'techwear_night_runner', name: '机能夜行者', nameEn: 'Techwear Night Runner', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是把身体整理成夜间移动工具的机能夜行者。造型入口：把身体整理成夜间移动工具的机能夜行者。母题：城市黑暗里的高效率穿行身体。张力：造型像装备，但绝不能变成战斗装。视觉证据：防水壳衣、黑色分层、斜挎包、束带、口袋和贴住肩胸腰腿的功能线条。边界：避免加入武器、军警身份或随机战术堆叠。', defEn: 'First read: a techwear night runner who organizes the body into a tool for moving through the city at night. Styling entry: a techwear night runner who organizes the body into a tool for moving through the city at night. Motif: an efficient urban traversal body. Tension: the look resembles gear but must not become combat equipment. Visual evidence: waterproof shell, black layering, sling bag, straps, pockets, and functional lines gripping shoulders, chest, waist, and legs. Boundary: avoid add weapons, military-police identity, or random tactical stacking.', ontologyLevel: 2, eras: contemporaryEras, tags: ['techwear', 'night_runner', 'urban'] },
  { id: 'urban_ninja_commuter', name: '都市忍者通勤者', nameEn: 'Urban Ninja Commuter', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是在人群里降低可见度的黑色通勤者，不是真的忍者。造型入口：在人群里降低可见度的黑色通勤者，不是真的忍者。母题：公共交通系统中的隐身轮廓。张力：他只是去上班，却把通勤穿成消失术。视觉证据：黑色机能外套、口罩或高领、地铁卡、压低帽檐、包带遮挡和快速步伐。边界：避免写成古代忍者、刺客或战斗角色。', defEn: 'First read: a black-clad commuter lowering visibility inside crowds, not a literal ninja. Styling entry: a black-clad commuter lowering visibility inside crowds, not a literal ninja. Motif: a hidden silhouette within public transit systems. Tension: he is only commuting, yet dresses the commute like a disappearance technique. Visual evidence: black technical jacket, mask or high collar, transit card, lowered brim, obscuring straps, and fast steps. Boundary: avoid making him an ancient ninja, assassin, or combat character.', ontologyLevel: 2, eras: contemporaryEras, tags: ['urban_ninja', 'commuter', 'mask'] },
  { id: 'goretex_rain_cultist', name: 'Gore-Tex雨夜信徒', nameEn: 'Gore-Tex Rain Cultist', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是把防水材质当成信仰展示的雨夜机能人物。造型入口：把防水材质当成信仰展示的雨夜机能人物。母题：城市天气里的材料崇拜者。张力：他站在雨中，却让“保持干燥”成为一种冷静权力。视觉证据：帽兜、水珠、防水拉链、黑伞、挺起肩线、干净手套和冷光路面反射。边界：避免写成宗教信徒或普通雨衣路人。', defEn: 'First read: a rainy-night techwear figure displaying waterproof material like a belief. Styling entry: a rainy-night techwear figure displaying waterproof material like a belief. Motif: a material devotee inside urban weather. Tension: he stands in rain while making dryness feel like calm power. Visual evidence: hood, water beads, waterproof zippers, black umbrella, structured shoulders, clean gloves, and cold pavement reflections. Boundary: avoid making him a religious cultist or ordinary raincoat pedestrian.', ontologyLevel: 2, eras: contemporaryEras, tags: ['goretex', 'rain', 'techwear'] },
  { id: 'cyber_gorpcore_hiker', name: '赛博Gorpcore城市徒步者', nameEn: 'Cyber Gorpcore Urban Hiker', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是把户外徒步语法搬进城市街道的赛博Gorpcore人物。造型入口：把户外徒步语法搬进城市街道的赛博Gorpcore人物。母题：能长时间行走、补给、穿越公共空间的城市身体。张力：登山装备被城市化，赛博感只作为贴身小细节出现。视觉证据：户外壳衣、荧光绳扣、轻量背包、城市徒步鞋、小灯条、反光材质和补给挂点。边界：避免写成真正登山者或全身科幻装甲。', defEn: 'First read: a cyber gorpcore figure moving outdoor hiking language into city streets. Styling entry: a cyber gorpcore figure moving outdoor hiking language into city streets. Motif: an urban body built to walk, resupply, and cross public space for long hours. Tension: hiking gear is urbanized while cyber feeling appears only in small close-to-body details. Visual evidence: outdoor shell, fluorescent cord locks, light pack, urban hiking shoes, small light strips, reflective material, and supply attachments. Boundary: avoid making a real mountaineer or full sci-fi armor.', ontologyLevel: 2, eras: contemporaryEras, tags: ['gorpcore', 'cyber', 'hiker'] },
  { id: 'black_mask_delivery_rider', name: '黑面罩外卖骑手', nameEn: 'Black-Masked Delivery Rider', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是被路线、时间和保温箱压成前倾姿态的黑面罩外卖骑手。造型入口：被路线、时间和保温箱压成前倾姿态的黑面罩外卖骑手。母题：平台劳动里的速度身体。张力：机能轮廓来自工作压力，而不是酷炫表演。视觉证据：骑行夹克、黑面罩、保温箱、手机支架、磨损手套、被箱体拉住的肩背和疲惫眼神。边界：避免写成帮派骑手或纯潮流机能模特。', defEn: 'First read: a black-masked delivery rider bent forward by route, time, and insulated box. Styling entry: a black-masked delivery rider bent forward by route, time, and insulated box. Motif: a speed body inside platform labor. Tension: the functional silhouette comes from work pressure, not cool performance. Visual evidence: riding jacket, black mask, delivery box, phone mount, worn gloves, shoulders pulled by the box, and tired eyes. Boundary: avoid making him a gang rider or pure techwear model.', eras: contemporaryEras, tags: ['delivery', 'rider', 'mask'] },
  { id: 'tactical_fashion_student', name: '战术风时装学生', nameEn: 'Tactical-Fashion Student', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是把战术结构当成时装态度的设计学院学生。造型入口：把战术结构当成时装态度的设计学院学生。母题：预算有限但概念过剩的年轻造型实验者。张力：挂点和口袋看似硬核，实际装着尺、笔、布样和作品集工具。视觉证据：多口袋背心、作品集筒、黑色短发、便宜面料、布样挂件和学生式自信。边界：避免生成武器、军装身份或真正战术任务。', defEn: 'First read: a fashion student using tactical structure as styling attitude. Styling entry: a fashion student using tactical structure as styling attitude. Motif: a young design experimenter with limited budget and excessive concept. Tension: attachment points and pockets look hard-edged but actually carry rulers, pens, swatches, and portfolio tools. Visual evidence: multi-pocket vest, portfolio tube, black short hair, cheap materials, fabric swatch hangers, and student confidence. Boundary: avoid generate weapons, military identity, or real tactical mission.', ontologyLevel: 2, eras: contemporaryEras, tags: ['tactical_fashion', 'student', 'portfolio'] },
  { id: 'night_train_platform_waiter', name: '夜班站台等待者', nameEn: 'Night-Train Platform Waiter', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是被夜班站台冷风固定住的等待者。造型入口：被夜班站台冷风固定住的等待者。母题：城市交通缝隙里的停滞身体。张力：他没有戏剧动作，却被屏幕光、轨道方向和等待时间压出强烈状态。视觉证据：长外套、耳机、票卡、缩起肩膀、手插口袋、脚尖朝轨道和被手机光切开的脸。边界：避免写成复杂剧情人物或旅行游客。', defEn: 'First read: a waiter on a night-train platform held still by cold wind. Styling entry: a waiter on a night-train platform held still by cold wind. Motif: a stalled body inside a gap of urban transit. Tension: there is no dramatic action, yet screen light, track direction, and waiting time create strong presence. Visual evidence: long coat, headphones, transit card, hunched shoulders, hands in pockets, toes toward the track, and a face cut by phone light. Boundary: avoid making a complex story character or tourist traveler.', eras: contemporaryEras, tags: ['platform', 'night', 'urban'] },
  { id: 'helmeted_moped_girl', name: '头盔机车女孩', nameEn: 'Helmeted Moped Girl', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是靠小型机车获得街口机动性的头盔女孩。造型入口：靠小型机车获得街口机动性的头盔女孩。母题：日常城市里的轻速度身体。张力：她不是重机骑士，却随时能拧钥匙离开。视觉证据：半盔、短夹克、钥匙扣、贴纸小机车、被头盔压过的发梢、微外撇站姿和握着钥匙的手。边界：避免写成硬派机车党或性感骑士海报。', defEn: 'First read: a helmeted girl whose small moped gives her street-corner mobility. Styling entry: a helmeted girl whose small moped gives her street-corner mobility. Motif: a light-speed body inside everyday city life. Tension: she is not a heavy biker, yet can turn the key and leave at any second. Visual evidence: half helmet, cropped jacket, keychain, stickered moped, helmet-flattened hair ends, slightly angled stance, and key-holding hand. Boundary: avoid making her a hard biker-gang member or sexy rider poster.', tags: ['moped', 'helmet', 'girl'] },
  { id: 'urban_explorer', name: '城市废墟探索者', nameEn: 'Urban Explorer', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是偷偷进入城市废弃空间的探索者。造型入口：偷偷进入城市废弃空间的探索者。母题：边缘空间里的低声行动身体。张力：他携带装备，却必须保持不显眼、不英雄化。视觉证据：头灯、手套、轻背包、耐磨裤、灰尘鞋底、贴近扶手和墙边的姿态。边界：避免写成冒险英雄、废土幸存者或大型探险队。', defEn: 'First read: an urban explorer sneaking into abandoned city spaces. Styling entry: an urban explorer sneaking into abandoned city spaces. Motif: a quiet action body inside marginal space. Tension: he carries gear but must remain inconspicuous and unheroic. Visual evidence: headlamp, gloves, light backpack, abrasion-resistant pants, dusty soles, and posture close to railings and walls. Boundary: avoid making him an adventure hero, wasteland survivor, or large expedition member.', risk: 'medium', tags: ['urban_explorer', 'ruin', 'gear'] },
  { id: 'near_future_subway_girl', name: '近未来地铁少女', nameEn: 'Near-Future Subway Girl', group: 'C. 机能 / 都市夜行', groupEn: 'C. Techwear / Urban Night Movement', def: '第一识别是被公共交通系统轻微改造过的近未来地铁女孩。造型入口：被公共交通系统轻微改造过的近未来地铁女孩。母题：日常生活中的贴身赛博身体。张力：未来感很小，却已经改变妆面、配饰和站姿。视觉证据：透明雨衣、电子耳饰、地铁卡、冷色屏幕反光、干净鞋底、站台等待姿态和贴身发光小物。边界：避免写成全息装甲、机器人或宏大赛博城市主角。', defEn: 'First read: a near-future subway girl subtly altered by public transit systems. Styling entry: a near-future subway girl subtly altered by public transit systems. Motif: a close-to-body cyber figure inside daily life. Tension: the future feeling is small, yet it has changed makeup, accessories, and stance. Visual evidence: transparent raincoat, electronic earrings, transit card, cool screen reflections, clean soles, platform waiting posture, and small wearable lights. Boundary: avoid making her holographic armor, a robot, or a grand cyberpunk city protagonist.', ontologyLevel: 3, eras: ['near_future', 'timeless'], risk: 'medium', tags: ['near_future', 'subway', 'girl'] },

  { id: 'y2k_mcbing_girl', name: 'Y2K McBling辣妹', nameEn: 'Y2K McBling Girl', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是把千禧年代的亮钻、低腰和手机挂饰穿成炫耀身体的Y2K辣妹。造型入口：把千禧年代的亮钻、低腰和手机挂饰穿成炫耀身体的Y2K辣妹。母题：早期数码社交里的高反光女性形象。张力：她像随时被闪光灯和镜面自拍捕捉，每个小物都要求被看见。视觉证据：低腰裤、亮钻腰带、翻盖手机、粉色塑料包、高光唇妆、长甲和抢眼腰线。边界：避免写成普通复古女孩或现代极简网红。', defEn: 'First read: a Y2K McBling girl wearing rhinestones, low-rise waist, and phone charms as a display body. Styling entry: a Y2K McBling girl wearing rhinestones, low-rise waist, and phone charms as a display body. Motif: a high-reflection female image from early digital social culture. Tension: she seems constantly caught by flash and mirror selfies, every small object asking to be seen. Visual evidence: low-rise pants, rhinestone belt, flip phone, pink plastic bag, glossy lips, long nails, and prominent waistline. Boundary: avoid making a generic retro girl or modern minimalist influencer.', tags: ['y2k', 'mcbing', 'girl'] },
  { id: 'shibuya_gyaru', name: '涩谷辣妹', nameEn: 'Shibuya Gyaru', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是亮、吵、主动社交的涩谷辣妹。造型入口：亮、吵、主动社交的涩谷辣妹。母题：街拍文化里外放自信的女性身体。张力：妆发和配饰很重，但身体姿态必须轻快、张扬、像一直在和朋友与镜头互动。视觉证据：晒黑妆、漂发、长甲、厚睫毛、手机挂饰、抬高下巴和外放手势。边界：避免写成温柔日系少女或单纯夜店装。', defEn: 'First read: a bright, loud, actively social Shibuya gyaru. Styling entry: a bright, loud, actively social Shibuya gyaru. Motif: an outwardly confident female body inside street-snap culture. Tension: makeup and accessories are heavy while posture remains quick, open, and constantly interacting with friends and camera. Visual evidence: tan makeup, bleached hair, long nails, heavy lashes, phone charms, raised chin, and open gestures. Boundary: avoid making a soft Japanese girl or simple clubwear look.', eras: ['modern', 'contemporary', 'timeless'], tags: ['gyaru', 'shibuya', 'japan'] },
  { id: 'harajuku_decora_kid', name: '原宿Decora青年', nameEn: 'Harajuku Decora Kid', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是把身体变成可爱小物展示架的原宿Decora青年。造型入口：把身体变成可爱小物展示架的原宿Decora青年。母题：过量装饰密度带来的自我发明。张力：可爱不是幼态身体，而是头发、胸口、包带和手腕被物件占满。视觉证据：彩色发夹、塑料玩具、叠戴项链、糖果色袜子、密集小物和被装饰重量轻微牵住的姿态。边界：避免写成儿童角色或随机彩色堆砌。', defEn: 'First read: a Harajuku Decora kid turning the body into a cute trinket display rack. Styling entry: a Harajuku Decora kid turning the body into a cute trinket display rack. Motif: self-invention through excessive decoration density. Tension: cuteness comes not from infantilized body but from hair, chest, bag straps, and wrists filled with objects. Visual evidence: colorful hair clips, plastic toys, stacked necklaces, candy socks, dense trinkets, and posture slightly pulled by decoration weight. Boundary: avoid making a child character or random color pile.', ontologyLevel: 2, tags: ['harajuku', 'decora', 'cute'] },
  { id: 'mall_goth_girl', name: '商场哥特女孩', nameEn: 'Mall Goth Girl', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是带着零售气味和青春期冷脸的商场哥特女孩。造型入口：带着零售气味和青春期冷脸的商场哥特女孩。母题：购物中心里的可购买黑暗感。张力：她想显得不可接近，但廉价银饰、塑料袋和过重眼妆仍暴露出青春与消费环境。视觉证据：黑眼线、链条裤、乐队T恤、厚底鞋、廉价银饰、购物中心灯光和故作冷淡的站姿。边界：避免写成真正恐怖哥特或高级黑暗名媛。', defEn: 'First read: a mall goth girl with retail smell and adolescent cold face. Styling entry: a mall goth girl with retail smell and adolescent cold face. Motif: purchasable darkness inside a shopping mall. Tension: she wants to seem inaccessible while cheap silver, plastic bags, and heavy eye makeup reveal youth and consumer setting. Visual evidence: black eyeliner, chain pants, band tee, platform shoes, cheap silver jewelry, mall light, and deliberately cold stance. Boundary: avoid making real horror goth or refined dark socialite.', tags: ['mall_goth', 'girl', 'youth'] },
  { id: 'scene_kid', name: 'Scene Kid', nameEn: 'Scene Kid', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是头像先于本人存在的早期社交网络Scene Kid。造型入口：头像先于本人存在的早期社交网络Scene Kid。母题：自拍角度、头发体积和夸张表情制造出来的网络身体。张力：身份更像个人主页视觉，而不是生活里的稳定形象。视觉证据：斜刘海遮眼、霓虹挑染、紧身裤、图案T恤、过高自拍角度和过度表情管理。边界：避免写成普通emo青年或现代精修网红。', defEn: 'First read: a Scene Kid whose avatar seems to exist before the person. Styling entry: a Scene Kid whose avatar seems to exist before the person. Motif: an early social-network body made from selfie angle, hair volume, and exaggerated expression. Tension: identity feels more like a profile-page visual than a stable daily self. Visual evidence: side bangs covering one eye, neon streaks, skinny jeans, graphic tee, high selfie angle, and over-managed expression. Boundary: avoid making a generic emo youth or modern polished influencer.', tags: ['scene_kid', 'emo_pop', 'internet'] },
  { id: 'myspace_party_girl', name: 'MySpace派对女孩', nameEn: 'MySpace Party Girl', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是被闪光灯打到发白的早期社交网站派对女孩。造型入口：被闪光灯打到发白的早期社交网站派对女孩。母题：夜生活被低质数码相机固定下来的身体。张力：她的精致和狼狈同时存在，像一张刚上传的过曝照片。视觉证据：闪光灯脸、派对手环、乱发、亮片裙、过曝皮肤、疲惫笑容和贴近镜头的姿态。边界：避免写成高级夜店大片或普通聚会女孩。', defEn: 'First read: a MySpace party girl bleached by camera flash. Styling entry: a MySpace party girl bleached by camera flash. Motif: a nightlife body fixed by low-quality digital camera. Tension: polish and mess coexist like a freshly uploaded overexposed photo. Visual evidence: flash-lit face, party wristband, messy hair, sequin dress, overexposed skin, tired smile, and posture close to the lens. Boundary: avoid making a refined club editorial or ordinary party girl.', risk: 'medium', tags: ['myspace', 'party_girl', 'flash'] },
  { id: 'cyber_egirl', name: '赛博E-girl', nameEn: 'Cyber E-Girl', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是被直播界面和屏幕光持续修饰的赛博E-girl。造型入口：被直播界面和屏幕光持续修饰的赛博E-girl。母题：轻虚拟社交环境里的可爱黑暗身体。张力：赛博感只在妆面、设备边缘和光线上发生，不把她变成真正机器人。视觉证据：双色头发、心形腮红、耳机、黑色网格内搭、屏幕光脸、贴纸设备和略带表演感的眼神。边界：避免生成机械义体或普通ACG少女。', defEn: 'First read: a cyber E-girl continuously styled by streaming interface and screen light. Styling entry: a cyber E-girl continuously styled by streaming interface and screen light. Motif: a cute-dark body inside lightly virtual social space. Tension: cyber feeling happens only in makeup, device edges, and light, without turning her into a real robot. Visual evidence: two-tone hair, heart blush, headset, black mesh layer, screen-lit face, stickered device, and slightly performative eyes. Boundary: avoid generate mechanical prosthetics or generic anime girl.', ontologyLevel: 2, eras: contemporaryEras, tags: ['egirl', 'cyber', 'internet'] },
  { id: 'internet_baddie', name: '网络Baddie', nameEn: 'Internet Baddie', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是每个角度都被社交平台训练过的网络Baddie。造型入口：每个角度都被社交平台训练过的网络Baddie。母题：强势自拍、商品展示和身体控制结合出的平台女性形象。张力：她看起来很有攻击性，但所有攻击性都经过镜前排练。视觉证据：锋利眉眼、长甲、贴身穿搭、高控制发型、镜前姿态、亮皮肤和像展示商品一样精准的手势。边界：避免写成普通性感角色或街头混混。', defEn: 'First read: an internet baddie trained by social-platform angles. Styling entry: an internet baddie trained by social-platform angles. Motif: a platform female image combining dominant selfie, product display, and body control. Tension: she appears aggressive, but every aggression is mirror-rehearsed. Visual evidence: sharp brows and eyes, long nails, bodycon styling, controlled hair, mirror pose, bright skin, and hands precise like product display. Boundary: avoid making a generic sexy character or street thug.', risk: 'medium', tags: ['baddie', 'internet', 'makeup'] },
  { id: 'kawaii_phone_charm_girl', name: '手机挂饰可爱女孩', nameEn: 'Phone-Charm Kawaii Girl', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是随身小物堆叠出可爱感的手机挂饰女孩。造型入口：随身小物堆叠出可爱感的手机挂饰女孩。母题：日常收藏癖通过柔软材质和小尺寸物件包围身体。张力：可爱必须来自物品系统，而不是幼态身体。视觉证据：手机挂饰、毛绒包、浅色针织、亮晶眼妆、小步站姿、包带小物和低声珍惜物件的手势。边界：避免写成儿童化人物。', defEn: 'First read: a phone-charm kawaii girl whose cuteness comes from accumulated carry objects. Styling entry: a phone-charm kawaii girl whose cuteness comes from accumulated carry objects. Motif: everyday collecting surrounding the body through soft materials and small objects. Tension: cuteness must come from the object system, not an infantilized body. Visual evidence: phone charms, plush bag, pale knitwear, glitter eye makeup, small-step stance, bag-strap trinkets, and hands carefully holding objects. Boundary: avoid making an infantilized character.', tags: ['kawaii', 'phone_charm', 'girl'] },
  { id: 'bubblegum_pop_fan', name: '泡泡糖流行粉丝', nameEn: 'Bubblegum-Pop Fan', group: 'D. Y2K / 辣妹 / 网络甜心', groupEn: 'D. Y2K / Gyaru / Internet Babe', def: '第一识别是把偶像周边和糖果色符号贴满身体的泡泡糖流行粉丝。造型入口：把偶像周边和糖果色符号贴满身体的泡泡糖流行粉丝。母题：粉丝依恋变成可穿戴装饰。张力：她不是偶像本人，而是被偶像商品和兴奋手势包围的观看者。视觉证据：偶像周边、糖果色上衣、贴纸相册、亮色发绳、胸牌、手机壳和过度兴奋的手部动作。边界：避免写成流行歌手或普通甜妹。', defEn: 'First read: a bubblegum-pop fan covering the body with idol merch and candy-colored signs. Styling entry: a bubblegum-pop fan covering the body with idol merch and candy-colored signs. Motif: fan attachment turned into wearable decoration. Tension: she is not the idol, but a viewer surrounded by idol goods and excited gestures. Visual evidence: idol merch, candy-colored top, sticker album, bright hair ties, badges, phone case, and overexcited hands. Boundary: avoid making a pop singer or generic sweet girl.', tags: ['bubblegum_pop', 'fan', 'merch'] },

  { id: 'warehouse_raver', name: '仓库Raver', nameEn: 'Warehouse Raver', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是身体被低频节拍推着向前的仓库Raver。造型入口：身体被低频节拍推着向前的仓库Raver。母题：为长时间跳舞而存在的地下派对身体。张力：衣服不为漂亮而为耐受服务：透气、脏、贴汗、能动。视觉证据：汗湿背心、腕带、宽裤、湿发、前倾肩颈、膝盖弹性和被音乐压出的表情。边界：避免写成普通夜店自拍或舞台歌手。', defEn: 'First read: a warehouse raver whose body is pushed forward by bass. Styling entry: a warehouse raver whose body is pushed forward by bass. Motif: an underground party body built for hours of dancing. Tension: clothing serves endurance rather than prettiness: breathable, dirty, sweat-stuck, able to move. Visual evidence: sweaty tank, wristband, wide pants, wet hair, forward neck-shoulders, elastic knees, and a face pressed by sound. Boundary: avoid making a normal club selfie or stage singer.', risk: 'medium', tags: ['rave', 'warehouse', 'club'] },
  { id: 'berlin_club_door_girl', name: '柏林夜店门口女孩', nameEn: 'Berlin Club Door Girl', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是站在夜店门口、用沉默和冷脸筛选他人的柏林式女孩。造型入口：站在夜店门口、用沉默和冷脸筛选他人的柏林式女孩。母题：门口权力的亚文化身体。张力：她不是华丽夜店装扮，而是用全黑材质、极简首饰和拒绝解释的眼神制造门槛。视觉证据：全黑穿搭、冷脸、沉默站姿、极简银饰、手臂抱起和不被取悦的表情。边界：避免写成夜店女郎或保安。', defEn: 'First read: a Berlin club-door girl screening others through silence and cold face. Styling entry: a Berlin club-door girl screening others through silence and cold face. Motif: a subcultural body of door power. Tension: she is not glamorous clubwear but creates a threshold through all-black materials, minimal jewelry, and eyes that refuse explanation. Visual evidence: all-black outfit, cold face, silent stance, minimal silver jewelry, crossed arms, and an unpleased expression. Boundary: avoid making a club hostess or security guard.', tags: ['berlin_club', 'door', 'girl'] },
  { id: 'industrial_techno_dancer', name: '工业Techno舞者', nameEn: 'Industrial Techno Dancer', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是像机器重复动作一样跳舞的工业Techno舞者。造型入口：像机器重复动作一样跳舞的工业Techno舞者。母题：身体被节拍切成短促单元的地下舞池人。张力：他不服务观众表情，只服务重复、硬度和低光下的节奏。视觉证据：黑色网眼、厚底靴、金属耳饰、剃短发或湿发、微弯膝盖、短促手臂和无表情脸。边界：避免写成普通舞者或机器人。', defEn: 'First read: an industrial techno dancer moving like repeated machine action. Styling entry: an industrial techno dancer moving like repeated machine action. Motif: an underground dancefloor body cut into short units by beat. Tension: the face serves no audience, only repetition, hardness, and rhythm in low light. Visual evidence: black mesh, platform boots, metal earrings, shaved or wet hair, slightly bent knees, clipped arms, and expressionless face. Boundary: avoid making a generic dancer or robot.', ontologyLevel: 2, tags: ['industrial', 'techno', 'dancer'] },
  { id: 'afterparty_socialite', name: 'Afterparty社交玩家', nameEn: 'Afterparty Social Player', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是凌晨后半场仍不肯离开的Afterparty社交玩家。造型入口：凌晨后半场仍不肯离开的Afterparty社交玩家。母题：被夜晚磨损但还在运转的社交身体。张力：精致已经皱掉，魅力却来自继续留在场内的疲惫坚持。视觉证据：凌晨墨镜、皱掉的闪片衣、松开发型、手机消息、疲惫笑容和仍在寻找下一场对话的站姿。边界：避免写成刚入场的派对新人。', defEn: 'First read: an afterparty social player refusing to leave in the late hours. Styling entry: an afterparty social player refusing to leave in the late hours. Motif: a social body worn by night but still operating. Tension: polish is wrinkled, while charm comes from tired persistence in the room. Visual evidence: dawn sunglasses, wrinkled sequins, loosened hair, phone messages, tired smile, and posture still seeking the next conversation. Boundary: avoid making a fresh party newcomer.', risk: 'medium', tags: ['afterparty', 'social', 'nightlife'] },
  { id: 'drag_ballroom_kid', name: 'Ballroom青年', nameEn: 'Ballroom Kid', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是把身份作为类别提交给舞池评判的Ballroom青年。造型入口：Vogue手势、夸张肩线和正面评判站姿。母题：自造贵族感和表演化身份。张力：姿态既是舞蹈也是宣告，下巴、手腕、髋部都在说“我属于这个类别”。视觉证据：Vogue手势、夸张肩线、亮片或紧身面料、正面评判站姿和像被掌声雕刻过的身体角度。边界：避免普通派对舞者。', defEn: 'First read: a Ballroom kid submitting identity as a category to the floor. Styling entry: Vogue hands, exaggerated shoulders, and judged frontal stance. Motif: self-made aristocracy and performed identity. Tension: posture is both dance and declaration, with chin, wrist, and hips saying “I belong to this category.” Visual evidence: Vogue hands, exaggerated shoulders, sequins or body-hugging fabric, judged frontal stance, and body angles shaped by applause. Boundary: avoid a normal party dancer.', tags: ['ballroom', 'vogue', 'chosen_family'] },
  { id: 'goa_trance_nomad', name: 'Goa Trance游牧者', nameEn: 'Goa Trance Nomad', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是带着户外电子节奏和旅行痕迹的Goa Trance游牧者。造型入口：带着户外电子节奏和旅行痕迹的Goa Trance游牧者。母题：太阳、手工饰物和流动布料组成的节庆身体。张力：他像四处移动，却所有物件都能随节拍一起晃动。视觉证据：宽松布料、荧光纹样、赤脚或凉鞋、旅行饰物、晒旧皮肤、手工痕迹和流动站姿。边界：避免写成普通背包客或舞台DJ。', defEn: 'First read: a Goa Trance nomad carrying outdoor electronic rhythm and travel traces. Styling entry: a Goa Trance nomad carrying outdoor electronic rhythm and travel traces. Motif: a festival body made from sun, handmade objects, and flowing cloth. Tension: he seems always moving while every object can sway with rhythm. Visual evidence: loose textiles, fluorescent patterns, bare feet or sandals, travel jewelry, sun-aged skin, handmade traces, and flowing stance. Boundary: avoid making a normal backpacker or stage DJ.', ontologyLevel: 2, risk: 'medium', tags: ['goa_trance', 'nomad', 'festival'] },
  { id: 'cyber_rave_android_fan', name: '赛博Rave仿生粉丝', nameEn: 'Cyber-Rave Android Fan', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是把仿生感穿成派对妆面的赛博Rave粉丝。造型入口：把仿生感穿成派对妆面的赛博Rave粉丝。母题：非人感被LED、银色皮肤妆和透明材料轻度制造的夜生活身体。张力：他像仿生人粉丝，但身体仍是人。视觉证据：LED饰品、银色皮肤妆、透明塑料、发光线缆、僵硬可爱的表情和略机械的舞池站姿。边界：避免变成真正机器人或战斗赛博角色。', defEn: 'First read: a cyber-rave fan wearing android feeling as party makeup. Styling entry: a cyber-rave fan wearing android feeling as party makeup. Motif: a nightlife body where nonhuman feeling is lightly produced by LEDs, silver skin makeup, and transparent materials. Tension: they resemble an android fan while remaining human. Visual evidence: LED accessories, silver skin makeup, transparent plastic, glowing cables, stiff-cute expression, and slightly mechanical dancefloor stance. Boundary: avoid turn into a real robot or combat cyber character.', ontologyLevel: 3, eras: ['near_future', 'timeless'], risk: 'medium', tags: ['cyber_rave', 'android_makeup', 'party'] },
  { id: 'club_kid_90s', name: '90年代Club Kid', nameEn: '1990s Club Kid', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是把自己发明成夜生活造型事件的90年代Club Kid。造型入口：把自己发明成夜生活造型事件的90年代Club Kid。母题：派对制服被怪诞妆容、玩具配饰和过量色块主动设计出来。张力：造型可以荒唐，但不是随机乱穿。视觉证据：怪诞妆容、夸张头饰、玩具配饰、过量色块、戏剧站姿和“我就是今晚事件”的表情。边界：避免写成普通小丑或随机狂欢者。', defEn: 'First read: a 1990s Club Kid inventing themselves as a nightlife styling event. Styling entry: a 1990s Club Kid inventing themselves as a nightlife styling event. Motif: a party uniform deliberately built from bizarre makeup, toy accessories, and excessive color blocks. Tension: the look may be absurd but not random. Visual evidence: bizarre makeup, exaggerated headpiece, toy accessories, excessive color, theatrical stance, and a face saying “I am tonight’s event”. Boundary: avoid making a generic clown or random reveler.', ontologyLevel: 2, risk: 'medium', tags: ['club_kid', '90s', 'nightlife'] },
  { id: 'kandi_raver', name: 'Kandi Raver', nameEn: 'Kandi Raver', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是把友好交换仪式直接戴在手腕和胸口的Kandi Raver。造型入口：把友好交换仪式直接戴在手腕和胸口的Kandi Raver。母题：糖果色社群亲密感。张力：天真符号很多，但身体仍属于成人Rave环境和长时间跳舞。视觉证据：彩珠手链、荧光色、微笑符号、短上衣、交换手势、腕部堆叠和明亮到过量的色彩。边界：避免写成儿童化可爱或普通节日游客。', defEn: 'First read: a Kandi Raver wearing friendly exchange ritual directly on wrists and chest. Styling entry: a Kandi Raver wearing friendly exchange ritual directly on wrists and chest. Motif: candy-colored community intimacy. Tension: innocent symbols are abundant while the body still belongs to adult rave space and long dancing. Visual evidence: beaded bracelets, neon colors, smile symbols, cropped top, exchange gesture, wrist stacking, and brightness pushed to excess. Boundary: avoid making infantilized cuteness or generic festival tourist.', ontologyLevel: 2, tags: ['kandi', 'raver', 'neon'] },
  { id: 'nightlife_photographer', name: '夜生活摄影师', nameEn: 'Nightlife Photographer', group: 'E. 夜店 / Rave / 派对地下', groupEn: 'E. Club / Rave / Underground Party', def: '第一识别是比所有参与者都更清醒、在闪光灯边缘工作的夜生活摄影师。造型入口：比所有参与者都更清醒、在闪光灯边缘工作的夜生活摄影师。母题：人群中的职业旁观者。张力：他进入派对却不完全属于派对，身体永远侧身挤过人群寻找下一张脸。视觉证据：闪光灯相机、黑衣、相机腕带、半眯眼、手指贴着快门和被闪光灯反复切亮的脸。边界：避免写成派对主角或普通摄影爱好者。', defEn: 'First read: a nightlife photographer more sober than the participants, working at the edge of flash. Styling entry: a nightlife photographer more sober than the participants, working at the edge of flash. Motif: a professional observer inside the crowd. Tension: he enters the party without fully belonging to it, body always slipping sideways for the next face. Visual evidence: flash camera, black clothing, camera wrist strap, narrowed eyes, finger on shutter, and a face repeatedly cut by flash. Boundary: avoid making a party protagonist or casual photography hobbyist.', tags: ['nightlife', 'photographer', 'flash'] },

  { id: 'graffiti_writer', name: '涂鸦写手', nameEn: 'Graffiti Writer', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是比脸更依赖签名动作成立的涂鸦写手。造型入口：比脸更依赖签名动作成立的涂鸦写手。母题：城市墙面上的手部速度和边缘控制。张力：他靠近墙、收紧肩、随时警觉，身份被罐声和指尖颜色替代。视觉证据：喷漆罐、手套、口罩、沾色指尖、背包罐声、贴墙站姿和检查边缘的眼神。边界：避免写成普通街头画家或持械犯罪者。', defEn: 'First read: a graffiti writer whose identity relies more on tagging motion than face. Styling entry: a graffiti writer whose identity relies more on tagging motion than face. Motif: hand speed and edge control on city walls. Tension: he stays close to the wall, shoulders tight, always alert, with identity replaced by can rattle and stained fingertips. Visual evidence: spray cans, gloves, mask, paint-stained fingers, cans in backpack, wall-hugging stance, and eyes checking edges. Boundary: avoid making a generic street painter or armed criminal.', risk: 'medium', tags: ['graffiti', 'writer', 'tag'] },
  { id: 'train_bomber', name: '列车涂鸦轰炸者', nameEn: 'Train Graffiti Bomber', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是围绕列车车身和撤离速度组织身体的涂鸦轰炸者。造型入口：围绕列车车身和撤离速度组织身体的涂鸦轰炸者。母题：高速、非法边缘和短时间喷涂构成的夜间身影。张力：造型重点是快，不是暴力。视觉证据：喷漆背包、深色帽衫、脏鞋底、半开拉链、未摘手套、反光轨道边缘和随时离开车身旁的警戒站姿。边界：避免写成战斗罪犯或悠闲艺术家。', defEn: 'First read: a train graffiti bomber whose body is organized around train side and escape speed. Styling entry: a train graffiti bomber whose body is organized around train side and escape speed. Motif: a night figure made from speed, illegal edge, and short spray time. Tension: the styling is about quickness, not violence. Visual evidence: paint backpack, dark hoodie, dirty soles, half-open zipper, gloves still on, reflective rail edge, and alert stance ready to leave the train side. Boundary: avoid making a combat criminal or relaxed artist.', risk: 'medium', tags: ['train', 'graffiti_bomber', 'night'] },
  { id: 'stencil_art_activist', name: '模板涂鸦行动者', nameEn: 'Stencil-Art Activist', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是用纸模板和匿名遮挡快速投放符号的街头行动者。造型入口：用纸模板和匿名遮挡快速投放符号的街头行动者。母题：观点被压缩成可复制图形后的行动身体。张力：政治性不靠长叙事，而靠纸边、喷雾和手部速度成立。视觉证据：纸模板、黑色喷雾、卷筒袋、胶带、低调深色衣服、匿名遮挡和快速后退查看的动作。边界：避免写成演讲者或普通海报设计师。', defEn: 'First read: a stencil-art activist quickly deploying symbols through paper stencils and anonymity. Styling entry: a stencil-art activist quickly deploying symbols through paper stencils and anonymity. Motif: an action body after opinion is compressed into repeatable graphics. Tension: politics does not rely on long narrative but on paper edges, spray, and hand speed. Visual evidence: paper stencils, black spray, tube bag, tape, low-profile dark clothing, anonymous concealment, and a quick step back to check. Boundary: avoid making a speaker or ordinary poster designer.', risk: 'medium', tags: ['stencil', 'activist', 'street_art'] },
  { id: 'mural_community_artist', name: '社区壁画艺术家', nameEn: 'Community Mural Artist', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是公开面对墙面和社区空间工作的壁画艺术家。造型入口：公开面对墙面和社区空间工作的壁画艺术家。母题：公共创作身体。张力：她不像非法涂鸦那样躲藏，脸、动作和颜料痕迹都可以被看见。视觉证据：颜料桶、宽刷、梯子、旧工装裤、大面积颜料痕、伸展开的手臂和面向墙面的开放姿态。边界：避免写成美术馆画家或夜间涂鸦写手。', defEn: 'First read: a community mural artist working openly with wall and public space. Styling entry: a community mural artist working openly with wall and public space. Motif: a public-making body. Tension: unlike illegal graffiti, face, movement, and paint marks can all be seen. Visual evidence: paint buckets, wide brush, ladder, old work pants, large paint marks, extended arms, and open posture facing the wall. Boundary: avoid making a gallery painter or night graffiti writer.', tags: ['mural', 'community', 'artist'] },
  { id: 'wheatpaste_poster_kid', name: '街贴海报青年', nameEn: 'Wheatpaste Poster Kid', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是把纸张临时压进城市墙面的街贴海报青年。造型入口：把纸张临时压进城市墙面的街贴海报青年。母题：海报、浆糊和撤退查看动作组成的临时占领者。张力：图像不是永久壁画，而是随时可能被撕掉的城市表皮。视觉证据：海报卷、浆糊刷、水桶、撕裂纸边、沾胶袖口、抹平动作和快速后退查看的身体。边界：避免写成正式广告工或室内设计师。', defEn: 'First read: a wheatpaste poster kid pressing paper temporarily into city walls. Styling entry: a wheatpaste poster kid pressing paper temporarily into city walls. Motif: a temporary occupier made of posters, paste, and step-back checking. Tension: the image is not permanent mural but city skin that may be torn away. Visual evidence: poster rolls, paste brush, bucket, torn paper edges, glue-stained cuffs, smoothing motion, and a body stepping back quickly to check. Boundary: avoid making a formal ad worker or interior designer.', tags: ['wheatpaste', 'poster', 'street_art'] },
  { id: 'tagger_schoolgirl', name: 'Tagger女学生', nameEn: 'Tagger Schoolgirl', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是把学生规训和签名冲动藏在一起的Tagger女学生。造型入口：把学生规训和签名冲动藏在一起的Tagger女学生。母题：校服系统内部的小破坏。张力：书包和制服很干净，手指、袖口和课本边角却已经被记号笔占领。视觉证据：校服外套、记号笔、课本边角标签、袖口墨迹、干净书包和像刚藏起笔的眼神。边界：避免写成普通乖学生或成年街头罪犯。', defEn: 'First read: a tagger schoolgirl hiding student discipline and signature impulse together. Styling entry: a tagger schoolgirl hiding student discipline and signature impulse together. Motif: small sabotage inside a uniform system. Tension: bag and uniform stay clean while fingers, cuffs, and textbook corners are already claimed by marker. Visual evidence: school jacket, marker, tagged textbook corners, inked cuffs, clean bag, and eyes like she just hid the pen. Boundary: avoid making a normal good student or adult street criminal.', risk: 'medium', tags: ['tagger', 'schoolgirl', 'marker'] },
  { id: 'street_calligrapher', name: '街头书法写手', nameEn: 'Street Calligraphy Writer', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是把传统腕力和笔画节奏带到城市表面的街头书法写手。造型入口：把传统腕力和笔画节奏带到城市表面的街头书法写手。母题：古典训练与街头墙面的碰撞。张力：他不是安静书斋里的书法家，而是用站距、肩膀和大号笔刷占据墙面的人。视觉证据：大号笔刷、墨迹袖口、宽站距、发力手腕、传统字形训练和贴近墙面的身体张力。边界：避免写成古装文人或普通涂鸦喷漆者。', defEn: 'First read: a street calligraphy writer bringing traditional wrist force and stroke rhythm onto urban surfaces. Styling entry: a street calligraphy writer bringing traditional wrist force and stroke rhythm onto urban surfaces. Motif: the collision of classical training and street wall. Tension: he is not a quiet study-room calligrapher but someone occupying the wall through stance, shoulder, and large brush. Visual evidence: large brush, inked cuffs, wide stance, forceful wrist, trained letterforms, and body tension near the wall. Boundary: avoid making an ancient scholar or normal spray graffiti writer.', tags: ['calligraphy', 'street_art', 'brush'] },
  { id: 'sticker_slap_collector', name: '贴纸轰炸收藏者', nameEn: 'Sticker-Slap Collector', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是用贴纸本、口袋和快速手部动作占领城市小表面的贴纸轰炸收藏者。造型入口：用贴纸本、口袋和快速手部动作占领城市小表面的贴纸轰炸收藏者。母题：收藏癖和街头占位欲合并的身体。张力：他不需要大墙，只需要任何可贴的小面积。视觉证据：贴纸本、塞满口袋的贴纸、包身小图像、指甲边胶痕、快速手势和寻找电线杆或标牌边角的眼神。边界：避免写成普通文具收藏者。', defEn: 'First read: a sticker-slap collector claiming small urban surfaces through sticker book, pockets, and fast hands. Styling entry: a sticker-slap collector claiming small urban surfaces through sticker book, pockets, and fast hands. Motif: collecting obsession fused with street occupation. Tension: he does not need a large wall, only any tiny place that can be claimed. Visual evidence: sticker book, pockets full of stickers, tiny images on bag, adhesive near nails, fast hand gesture, and eyes hunting poles or sign corners. Boundary: avoid making a normal stationery collector.', tags: ['sticker', 'collector', 'street'] },
  { id: 'sketchbook_graffiti_girl', name: '黑本涂鸦女孩', nameEn: 'Blackbook Graffiti Girl', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是风格野心还停留在黑本和马克笔里的涂鸦女孩。造型入口：风格野心还停留在黑本和马克笔里的涂鸦女孩。母题：尚未上墙的字母训练身体。张力：她外表更内收安静，但眼睛一直在收集城市表面，手已经练熟了笔画。视觉证据：黑本草图、马克笔、彩色手指、背包侧袋笔、安静观察和把墙面当练习对象的眼神。边界：避免写成成熟涂鸦大师或普通画画女孩。', defEn: 'First read: a blackbook graffiti girl whose style ambition still lives in sketches and markers. Styling entry: a blackbook graffiti girl whose style ambition still lives in sketches and markers. Motif: a letter-training body before the wall. Tension: she looks inward and quiet while her eyes collect city surfaces and her hand already knows the strokes. Visual evidence: blackbook sketches, markers, colored fingers, pens in side pocket, quiet watching, and eyes treating walls as future practice. Boundary: avoid making a mature graffiti master or generic drawing girl.', tags: ['blackbook', 'graffiti_girl', 'sketch'] },
  { id: 'augmented_reality_tagger', name: 'AR涂鸦写手', nameEn: 'AR Graffiti Writer', group: 'F. 涂鸦 / 街头艺术', groupEn: 'F. Graffiti / Street Art', def: '第一识别是把街头写手警觉姿态带进近未来界面的AR涂鸦写手。造型入口：把街头写手警觉姿态带进近未来界面的AR涂鸦写手。母题：城市表面被数字层叠重新占领。张力：AR感只来自设备、屏幕反光和可见叠层，人物仍保留包、帽和街头警惕。视觉证据：手机扫描姿态、透明屏幕反光、数字贴纸界面、空墙前手势、斜挎包和随时确认周围的眼神。边界：避免写成全息法师或纯科技工程师。', defEn: 'First read: an AR graffiti writer bringing street-writer alertness into near-future interface. Styling entry: an AR graffiti writer bringing street-writer alertness into near-future interface. Motif: urban surface reclaimed through digital overlay. Tension: AR feeling comes only from device, screen reflection, and visible layers while the person keeps bag, cap, and street caution. Visual evidence: phone-scanning posture, transparent screen reflection, digital sticker interface, gestures before a blank wall, sling bag, and eyes checking surroundings. Boundary: avoid making a hologram mage or pure tech engineer.', ontologyLevel: 3, eras: ['near_future', 'timeless'], risk: 'medium', tags: ['ar', 'graffiti', 'digital'] },

  { id: 'sneakerhead_collector', name: '球鞋收藏玩家', nameEn: 'Sneakerhead Collector', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把脚和保存状态看得比脸更重要的球鞋收藏玩家。造型入口：把脚和保存状态看得比脸更重要的球鞋收藏玩家。母题：限量商品改变身体重心的收藏者。张力：他看似穿鞋，实际像在保护一件易损资产。视觉证据：限量球鞋、干净鞋面、鞋盒墙、抽签截图、低头检查鞋尖和走路时避免弄脏的姿态。边界：避免写成普通爱鞋青年或职业运动员。', defEn: 'First read: a sneakerhead collector who treats feet and preservation as more important than face. Styling entry: a sneakerhead collector who treats feet and preservation as more important than face. Motif: a collector whose body center is altered by limited goods. Tension: he seems to wear shoes while actually protecting a fragile asset. Visual evidence: limited sneakers, clean uppers, shoebox wall, raffle screenshots, checking the toe box, and walking as if avoiding dirt. Boundary: avoid making a generic shoe lover or athlete.', tags: ['sneakerhead', 'collector', 'hype'] },
  { id: 'hypebeast_drop_hunter', name: 'Drop抢购潮流玩家', nameEn: 'Drop-Hunting Hypebeast', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是被发售时间、排队和库存刷新支配的Drop抢购潮流玩家。造型入口：被发售时间、排队和库存刷新支配的Drop抢购潮流玩家。母题：消费仪式里的紧张等待身体。张力：服装是战利品，但姿态永远还在等待下一次确认。视觉证据：排队手环、联名外套、购物袋、手机倒计时、紧张眼神、刷新动作和冷风里抱臂的站姿。边界：避免复制真实logo，也不要写成普通购物者。', defEn: 'First read: a drop-hunting hypebeast ruled by release time, queue, and stock refresh. Styling entry: a drop-hunting hypebeast ruled by release time, queue, and stock refresh. Motif: a tense waiting body inside consumption ritual. Tension: clothing is trophy while posture is still waiting for the next confirmation. Visual evidence: queue wristband, collaboration jacket, shopping bags, phone countdown, tense eyes, refresh gesture, and arms crossed in cold air. Boundary: avoid copy real logos or make a normal shopper.', tags: ['hypebeast', 'drop', 'queue'] },
  { id: 'streetwear_reseller', name: '街头潮牌转卖商', nameEn: 'Streetwear Reseller', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把潮流商品当作金融仓位管理的街头潮牌转卖商。造型入口：把潮流商品当作金融仓位管理的街头潮牌转卖商。母题：商品、验真和价格贴纸组成的计算身体。张力：他穿得干净，但眼神看商品比看人更多。视觉证据：库存箱、验真灯、价格贴纸、塑封袋、冷静手势、移动仓库般的包和带估价感的目光。边界：避免写成普通潮人或实体店老板。', defEn: 'First read: a streetwear reseller managing hype goods like financial positions. Styling entry: a streetwear reseller managing hype goods like financial positions. Motif: a calculating body made from product, legit check, and price stickers. Tension: he dresses cleanly while looking at goods more than people. Visual evidence: stock boxes, legit-check light, price stickers, plastic sleeves, calm hands, bag like a mobile warehouse, and valuation gaze. Boundary: avoid making a normal streetwear fan or store owner.', tags: ['reseller', 'streetwear', 'commerce'] },
  { id: 'archive_streetwear_nerd', name: 'Archive街头服饰考据者', nameEn: 'Archive Streetwear Nerd', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把旧季街头服饰当文献穿在身上的Archive考据者。造型入口：把旧季街头服饰当文献穿在身上的Archive考据者。母题：知识密度高过潮流热度的收藏身体。张力：他并不追求最新，而追求年份、吊牌和冷门细节带来的优越感。视觉证据：旧季外套、保存吊牌、褪色印花、冷门年份、小心整理衣摆的手和克制但得意的表情。边界：避免写成普通复古玩家。', defEn: 'First read: an archive streetwear nerd wearing old-season garments like documents. Styling entry: an archive streetwear nerd wearing old-season garments like documents. Motif: a collecting body where knowledge density exceeds hype. Tension: he does not chase newness but the superiority of year, tag, and obscure detail. Visual evidence: old-season jacket, preserved tag, faded print, obscure year, hands carefully arranging hem, and restrained yet superior expression. Boundary: avoid making a generic vintage fan.', tags: ['archive', 'streetwear', 'nerd'] },
  { id: 'supreme_line_kid', name: 'Supreme排队青年', nameEn: 'Supreme-Line Kid', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把发售队伍本身当成身份的街头排队青年。造型入口：折叠椅、连帽衫、滑板店门口和抱臂等待。母题：标志色块和等待仪式塑造出的消费身体。张力：他还没买到商品，已经通过位置、折叠椅和冷风姿态证明参与感。视觉证据：红白街头标识氛围、折叠椅、连帽衫、滑板店门口、抱臂等待和压低期待的脸。边界：避免直接复制真实logo。', defEn: 'First read: a streetwear line kid whose identity comes from the release queue itself. Styling entry: folding chair, hoodie, skate-shop doorway, and arms-crossed waiting. Motif: a consumption body shaped by bold label color and waiting ritual. Tension: before buying anything, he has already proved participation through position, folding chair, and cold-air posture. Visual evidence: red-white street-label atmosphere, folding chair, hoodie, skate-shop doorway, arms-crossed waiting, and a face suppressing expectation. Boundary: avoid direct real-logo copying.', tags: ['supreme', 'line', 'streetwear'] },
  { id: 'designer_toy_collector', name: '潮流玩具收藏者', nameEn: 'Designer-Toy Collector', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把童年物件当艺术资产管理的潮流玩具收藏者。造型入口：把童年物件当艺术资产管理的潮流玩具收藏者。母题：可爱商品被严肃收藏制度包住的身体。张力：物件很童趣，眼神和手势却认真到近乎荒唐。视觉证据：搪胶玩具、展示柜、限量编号、白手套或防尘布、克制身体和盯着小玩具估值的冷脸。边界：避免写成儿童玩具玩家。', defEn: 'First read: a designer-toy collector managing childhood objects as art assets. Styling entry: a designer-toy collector managing childhood objects as art assets. Motif: a body where cute goods are contained by serious collecting systems. Tension: objects are playful while gaze and hands are almost absurdly serious. Visual evidence: vinyl toys, display case, edition numbers, white gloves or dust cloth, restrained body, and cold face valuing a small toy. Boundary: avoid making a child toy player.', ontologyLevel: 2, tags: ['designer_toy', 'collector', 'vinyl'] },
  { id: 'luxury_streetwear_heir', name: '奢侈街头继承人', nameEn: 'Luxury Streetwear Heir', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把街头符号贵族化的奢侈街头继承人。造型入口：把街头符号贵族化的奢侈街头继承人。母题：资源保护过的潮流身体。张力：他借用街头语法，却通过材料、保养和松弛站姿显示从未真正匮乏。视觉证据：高端卫衣、珠宝、干净球鞋、车钥匙、昂贵面料维护感和懒得解释的姿态。边界：避免写成真正街头苦难角色或普通富二代。', defEn: 'First read: a luxury streetwear heir aristocratizing street signs. Styling entry: a luxury streetwear heir aristocratizing street signs. Motif: a hype body protected by resources. Tension: he borrows street grammar while material, maintenance, and relaxed stance reveal he never truly lacked anything. Visual evidence: luxury hoodie, jewelry, clean sneakers, car key, expensive material upkeep, and posture too relaxed to explain. Boundary: avoid making a real hardship street figure or generic rich kid.', risk: 'medium', tags: ['luxury_streetwear', 'heir', 'wealth'] },
  { id: 'sneaker_customizer', name: '球鞋改造师', nameEn: 'Sneaker Customizer', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是把球鞋拆开、改色、重组的人，而不是单纯穿球鞋的人。造型入口：把球鞋拆开、改色、重组的人，而不是单纯穿球鞋的人。母题：手作潮流身份。张力：商品崇拜被工作台、颜料和拆线工具改造成制作能力。视觉证据：颜料笔、拆线工具、鞋楦、围裙、手上色痕、桌面鞋料和低头处理鞋面边缘的姿态。边界：避免写成普通球鞋收藏者。', defEn: 'First read: a sneaker customizer who cuts, recolors, and rebuilds shoes rather than merely wearing them. Styling entry: a sneaker customizer who cuts, recolors, and rebuilds shoes rather than merely wearing them. Motif: a maker identity inside hype culture. Tension: product worship is turned into making ability through workbench, paint, and stitch tools. Visual evidence: paint pens, stitch tools, shoe last, apron, color marks on hands, table of shoe parts, and posture bent over an upper edge. Boundary: avoid making a normal sneaker collector.', tags: ['sneaker_custom', 'maker', 'shoe'] },
  { id: 'kicks_store_clerk', name: '球鞋店店员', nameEn: 'Sneaker Store Clerk', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是站在商品与顾客之间、掌握库存秘密的球鞋店店员。造型入口：站在商品与顾客之间、掌握库存秘密的球鞋店店员。母题：零售空间里的小型权力。张力：他礼貌服务，却知道谁能买到什么、哪双鞋还有码。视觉证据：鞋墙、工牌、干净员工穿搭、半拿出的鞋盒、熟客眼神和身体挡在顾客与货架之间的位置。边界：避免写成普通收银员或球鞋买家。', defEn: 'First read: a sneaker store clerk standing between product and customer, holding inventory secrets. Styling entry: a sneaker store clerk standing between product and customer, holding inventory secrets. Motif: small power inside retail space. Tension: he serves politely while knowing who can get what and which sizes remain. Visual evidence: shoe wall, name tag, clean staff styling, half-pulled shoebox, regular-customer gaze, and body positioned between customer and shelf. Boundary: avoid making a normal cashier or sneaker buyer.', tags: ['sneaker_store', 'clerk', 'retail'] },
  { id: 'fake_market_hype_kid', name: '假货市场潮流青年', nameEn: 'Replica-Market Hype Kid', group: 'G. 球鞋 / 潮流消费', groupEn: 'G. Sneakers / Hype Consumption', def: '第一识别是在夜市灯光和真假暧昧吊牌之间建立自信的假货市场潮流青年。造型入口：在夜市灯光和真假暧昧吊牌之间建立自信的假货市场潮流青年。母题：复制品仍然塑造身体姿态和社群欲望。张力：预算很低，但他仍用仿品完成一种进入潮流的资格感。视觉证据：仿品球鞋、塑料袋、夜市灯光、暧昧吊牌、低预算自信和故意展示鞋面的站姿。边界：避免把重点写成揭穿骗局或正品奢侈。', defEn: 'First read: a replica-market hype kid building confidence between night-market light and ambiguous tags. Styling entry: a replica-market hype kid building confidence between night-market light and ambiguous tags. Motif: how copies still shape posture and group desire. Tension: budget is low while replica goods still produce a sense of entry into hype culture. Visual evidence: replica sneakers, plastic bags, night-market lighting, ambiguous tags, low-budget confidence, and stance deliberately showing shoe uppers. Boundary: avoid making the focus scam exposure or authentic luxury.', risk: 'medium', tags: ['replica_market', 'hype', 'budget'] },

  { id: 'outlaw_biker', name: '机车帮派成员', nameEn: 'Outlaw Biker', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是用皮革、补丁和占地姿态建立公路帮派轮廓的机车成员。造型入口：用皮革、补丁和占地姿态建立公路帮派轮廓的机车成员。母题：厚重材料和路面威慑感组成的身体。张力：他可以有危险气息，但不应变成军装或战术兵。视觉证据：皮革背心、胸前补丁、油污、粗靴、车钥匙、外扩手臂和站得很占地方的重心。边界：避免生成武器堆叠或军警身份。', defEn: 'First read: an outlaw biker building road-gang silhouette through leather, patches, and space-claiming posture. Styling entry: an outlaw biker building road-gang silhouette through leather, patches, and space-claiming posture. Motif: a body made of heavy material and road intimidation. Tension: danger may be present but should not become military or tactical gear. Visual evidence: leather vest, chest patches, oil stains, heavy boots, keys, wide arms, and weight that takes up space. Boundary: avoid generate weapon stacking or police/military identity.', eras: industrialModernEras, risk: 'medium', tags: ['biker', 'outlaw', 'road'] },
  { id: 'cafe_racer_girl', name: 'Cafe Racer女孩', nameEn: 'Cafe-Racer Girl', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是把速度压成干净短线条的Cafe Racer女孩。造型入口：把速度压成干净短线条的Cafe Racer女孩。母题：利落、复古和轻叛逆的街口机车身体。张力：她不粗暴，反而用紧肩线、短腰线和头盔手势制造冷静速度感。视觉证据：短皮衣、半盔、复古机车手套、修身牛仔、手边头盔和像随时能启动的紧凑站姿。边界：避免写成重机帮派女郎。', defEn: 'First read: a cafe-racer girl compressing speed into clean short lines. Styling entry: a cafe-racer girl compressing speed into clean short lines. Motif: a neat, retro, lightly rebellious street-corner riding body. Tension: she is not rough but creates calm speed through tight shoulders, short waistline, and helmet gesture. Visual evidence: cropped leather jacket, half helmet, vintage riding gloves, slim denim, helmet held at side, and compact stance ready to start. Boundary: avoid making a heavy biker-gang girl.', eras: industrialModernEras, tags: ['cafe_racer', 'girl', 'motorcycle'] },
  { id: 'punk_biker_chick', name: '朋克机车女郎', nameEn: 'Punk Biker Chick', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是把铆钉、彩发和皮革边缘都变成刺的朋克机车女郎。造型入口：把铆钉、彩发和皮革边缘都变成刺的朋克机车女郎。母题：公路叛逆与朋克攻击性合并的身体。张力：她的危险感来自轮廓尖锐和怒气眼神，而不是武器。视觉证据：铆钉皮衣、彩色头发、破损牛仔、重靴、前倾下巴、撕裂布料和像会刮伤人的站姿。边界：避免写成性感机车海报或战斗角色。', defEn: 'First read: a punk biker chick turning studs, colored hair, and leather edges into spikes. Styling entry: a punk biker chick turning studs, colored hair, and leather edges into spikes. Motif: road rebellion fused with punk aggression. Tension: danger comes from sharp silhouette and angry eyes, not weapons. Visual evidence: studded leather, colored hair, ripped denim, heavy boots, forward chin, torn fabric, and a stance that seems to scratch. Boundary: avoid making a sexy biker poster or combat character.', eras: industrialModernEras, risk: 'medium', tags: ['punk', 'biker', 'chick'] },
  { id: 'bosozoku_youth', name: '暴走族青年', nameEn: 'Bosozoku Youth', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是把制服穿成挑衅仪式的暴走族青年。造型入口：把制服穿成挑衅仪式的暴走族青年。母题：年轻人过量姿态和改装机车文化合成的街头身体。张力：刺绣大字和夸张坐姿很高调，但仍要落在服装与车队符号上。视觉证据：特攻服、醒目刺绣、宽大衣摆、改装摩托、夸张坐姿和过分外放的年轻自信。边界：避免写成军装角色或真实暴力场面。', defEn: 'First read: a bosozoku youth wearing uniform as a provocation ritual. Styling entry: a bosozoku youth wearing uniform as a provocation ritual. Motif: a street body made from excessive youth posture and modified motorcycle culture. Tension: large embroidery and exaggerated sitting are loud but must remain clothing and convoy signs. Visual evidence: tokko-fuku coat, bold embroidery, wide coat tails, modified bike, exaggerated seated pose, and overly outward young confidence. Boundary: avoid making a military uniform character or real violence scene.', eras: ['modern', 'contemporary', 'timeless'], risk: 'medium', tags: ['bosozoku', 'japan', 'bike'] },
  { id: 'chopper_garage_mechanic', name: 'Chopper车库技师', nameEn: 'Chopper Garage Mechanic', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是围着改装车架工作、由劳动痕迹成立的Chopper车库技师。造型入口：围着改装车架工作、由劳动痕迹成立的Chopper车库技师。母题：手作机车文化里的粗糙工匠身体。张力：造型不靠摆酷，而靠油污、工具和长期接触机器的手。视觉证据：油污背心、工具腰带、黑指节、粗糙手部、旧衣料、低光车库和身体围着机器转的站姿。边界：避免写成普通修车工或机车模特。', defEn: 'First read: a chopper garage mechanic defined by labor traces around a custom frame. Styling entry: a chopper garage mechanic defined by labor traces around a custom frame. Motif: a rough craft body inside handmade motorcycle culture. Tension: the look does not pose as cool but comes from grease, tools, and hands long in contact with machines. Visual evidence: greasy vest, tool belt, black knuckles, rough hands, old fabric, low garage light, and posture orbiting the machine. Boundary: avoid making a generic mechanic or motorcycle model.', eras: industrialModernEras, tags: ['chopper', 'mechanic', 'garage'] },
  { id: 'desert_motorcycle_nomad', name: '沙漠机车游牧者', nameEn: 'Desert Motorcycle Nomad', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是被风沙、太阳和长路磨过的沙漠机车游牧者。造型入口：被风沙、太阳和长路磨过的沙漠机车游牧者。母题：荒路环境改写身体和衣料后的移动者。张力：他不是末世战士，而是长期路途让一切变干、褪色、有压痕。视觉证据：防尘镜、围巾、晒伤皮肤、褪色皮革、绑在车上的水袋、眼周压痕和干硬布料。边界：避免写成废土战斗角色。', defEn: 'First read: a desert motorcycle nomad worn by sand, sun, and long road. Styling entry: a desert motorcycle nomad worn by sand, sun, and long road. Motif: a mover whose body and fabric are rewritten by harsh route. Tension: he is not a wasteland warrior, but long travel has made everything dry, faded, and marked. Visual evidence: dust goggles, scarf, sunburned skin, faded leather, water bag tied to bike, pressure marks around eyes, and stiff fabric. Boundary: avoid making a wasteland combat character.', eras: industrialModernEras, tags: ['desert', 'motorcycle', 'nomad'] },
  { id: 'biker_bar_waitress', name: '机车酒吧女招待', nameEn: 'Biker-Bar Waitress', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是靠近机车圈但不属于帮派的酒吧女招待。造型入口：靠近机车圈但不属于帮派的酒吧女招待。母题：服务业疲惫与公路空间熟悉感合成的日常身体。张力：她说话少、站得稳，身体知道这里的规矩但不穿帮派身份。视觉证据：旧围裙、靴子、托盘、烟味头发、熟客式眼神、手腕疲惫和稳定站姿。边界：避免写成机车帮成员或性感酒吧招牌。', defEn: 'First read: a biker-bar waitress near biker circles but not part of the gang. Styling entry: a biker-bar waitress near biker circles but not part of the gang. Motif: a daily body made from service fatigue and familiarity with road spaces. Tension: she speaks little and stands steady, knowing the room’s rules without wearing gang identity. Visual evidence: old apron, boots, tray, smoke-scented hair, regular-customer gaze, tired wrists, and stable stance. Boundary: avoid making a biker-gang member or sexy bar sign.', eras: industrialModernEras, risk: 'medium', tags: ['biker_bar', 'waitress', 'road'] },
  { id: 'road_trip_grunge_couple', name: '公路Grunge旅人', nameEn: 'Road-Trip Grunge Traveler', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是把临时生活套在身上的公路Grunge旅人。造型入口：把临时生活套在身上的公路Grunge旅人。母题：加油站灰尘、睡眠不足和旧衣层次构成的移动状态。张力：重点不是浪漫故事，而是衣服和皮肤都像被路程临时安排。视觉证据：法兰绒、旧背包、凌乱头发、加油站灰尘、疲惫脸、随手套上的衣层和不稳定站姿。边界：避免写成情侣剧情或精致旅行穿搭。', defEn: 'First read: a road-trip grunge traveler wearing temporary life on the body. Styling entry: a road-trip grunge traveler wearing temporary life on the body. Motif: a moving state made from gas-station dust, sleep deprivation, and old clothing layers. Tension: the point is not romance story but clothes and skin arranged by the road. Visual evidence: flannel, old backpack, messy hair, gas-station dust, tired face, layers pulled on by hand, and unsettled stance. Boundary: avoid making a couple plot or polished travel outfit.', eras: industrialModernEras, tags: ['grunge', 'road_trip', 'traveler'] },
  { id: 'motorcycle_courier', name: '摩托信使', nameEn: 'Motorcycle Courier', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是把自己变成一条移动线路的摩托信使。造型入口：把自己变成一条移动线路的摩托信使。母题：任务型速度身体。张力：他不像浪漫骑士，所有装束都围绕路线、钥匙、刹车和包带压力。视觉证据：斜挎邮袋、皮手套、路线图、划痕头盔、前倾身体、勒住胸口的包带和永远接近钥匙或刹车的手指。边界：避免写成公路英雄。', defEn: 'First read: a motorcycle courier turning himself into a moving route. Styling entry: a motorcycle courier turning himself into a moving route. Motif: a task-speed body. Tension: he is not a romantic rider, all styling organized around route, key, brake, and strap pressure. Visual evidence: courier satchel, leather gloves, route map, scratched helmet, forward lean, strap cutting across chest, and fingers always near key or brake. Boundary: avoid making a road hero.', eras: industrialModernEras, tags: ['motorcycle', 'courier', 'speed'] },
  { id: 'neon_biker_gang_girl', name: '霓虹机车帮女孩', nameEn: 'Neon Biker-Gang Girl', group: 'H. 机车 / 叛逆公路', groupEn: 'H. Biker / Rebel Road', def: '第一识别是把夜路车队符号和冷色霓虹穿在身上的轻近未来机车帮女孩。造型入口：把夜路车队符号和冷色霓虹穿在身上的轻近未来机车帮女孩。母题：公路叛逆被赛博边缘发光改写后的身体。张力：赛博感沿车身、贴纸和衣边出现，而不是把身体机械化。视觉证据：黑色皮革、霓虹贴纸、反光护目镜、夜路车队标记、冷色轮廓和靠近机车的站姿。边界：避免生成义体机器人或战术帮派装。', defEn: 'First read: a neon biker-gang girl wearing night-convoy signs and cool neon in a light near-future register. Styling entry: a neon biker-gang girl wearing night-convoy signs and cool neon in a light near-future register. Motif: road rebellion rewritten by cyber edge-glow. Tension: cyber feeling appears along bike, stickers, and garment edges, not by mechanizing the body. Visual evidence: black leather, neon stickers, reflective goggles, night-convoy marks, cool silhouette, and stance close to the motorcycle. Boundary: avoid generate cyborg body or tactical gang gear.', ontologyLevel: 2, eras: contemporaryEras, risk: 'medium', tags: ['neon_biker', 'gang', 'girl'] },

  { id: 'punk_squat_kid', name: '朋克占屋青年', nameEn: 'Punk Squat Kid', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是把拒绝体面直接穿在身上的朋克占屋青年。造型入口：把拒绝体面直接穿在身上的朋克占屋青年。母题：破损居住状态和DIY政治符号组成的反主流身体。张力：衣服脏旧不是失败，而是立场。视觉证据：破皮衣、别针、手写布章、旧靴子、不太干净的层次、烂衣边和不向镜头道歉的站姿。边界：避免写成普通流浪者或舞台朋克造型。', defEn: 'First read: a punk squat kid wearing refusal of respectability directly on the body. Styling entry: a punk squat kid wearing refusal of respectability directly on the body. Motif: an anti-mainstream body made from damaged living conditions and DIY political signs. Tension: dirty old clothing is not failure but position. Visual evidence: torn leather, safety pins, handwritten patches, old boots, not-too-clean layers, frayed edges, and stance that does not apologize to the camera. Boundary: avoid making a generic homeless figure or stage punk costume.', risk: 'medium', tags: ['punk', 'squat', 'youth'] },
  { id: 'hardcore_show_kid', name: 'Hardcore演出青年', nameEn: 'Hardcore Show Kid', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是随时准备进入近距离冲撞的Hardcore演出青年。造型入口：随时准备进入近距离冲撞的Hardcore演出青年。母题：狭小演出空间里的身体压力。张力：造型不追求漂亮，而要让肘部、肩膀、拳头都像正在人群里移动。视觉证据：乐队T恤、护腕、短发、汗湿衣领、前压肩膀、紧拳和贴近舞台边缘的站姿。边界：避免写成职业格斗者或普通演唱会观众。', defEn: 'First read: a hardcore show kid ready for close-range impact. Styling entry: a hardcore show kid ready for close-range impact. Motif: body pressure inside cramped venue space. Tension: styling does not seek prettiness but makes elbows, shoulders, and fists feel in motion through the crowd. Visual evidence: band tee, wrist wraps, short hair, sweat-dark collar, forward shoulders, tight fists, and stance near the stage edge. Boundary: avoid making a professional fighter or normal concert attendee.', risk: 'medium', tags: ['hardcore', 'show', 'mosh'] },
  { id: 'emo_diary_girl', name: 'Emo日记女孩', nameEn: 'Emo Diary Girl', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是把伤感压进遮眼发型、手写本和内收肩膀里的Emo日记女孩。造型入口：把伤感压进遮眼发型、手写本和内收肩膀里的Emo日记女孩。母题：情绪自我记录变成造型。张力：她不需要讲故事，黑色细节、低嘴角和抱紧小物的动作已经说明内向压力。视觉证据：黑色刘海、浓眼线、耳机、手写本、抱在胸前的小物、内扣肩膀和避开正视的眼神。边界：避免写成可爱甜妹或戏剧哭泣。', defEn: 'First read: an emo diary girl pressing sadness into eye-covering hair, notebook, and inward shoulders. Styling entry: an emo diary girl pressing sadness into eye-covering hair, notebook, and inward shoulders. Motif: emotional self-recording turned into styling. Tension: she needs no story because black details, lowered mouth, and held objects already show inward pressure. Visual evidence: black bangs, heavy eyeliner, headphones, handwritten notebook, small object held to chest, inward shoulders, and gaze avoiding direct contact. Boundary: avoid making a cute sweet girl or melodramatic crying.', risk: 'medium', tags: ['emo', 'diary', 'girl'] },
  { id: 'riot_grrrl_zine_maker', name: 'Riot Grrrl小志作者', nameEn: 'Riot Grrrl Zine Maker', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是把DIY出版物和身体穿搭绑在一起的Riot Grrrl小志作者。造型入口：把DIY出版物和身体穿搭绑在一起的Riot Grrrl小志作者。母题：复印、剪贴和手写标语进入服装后的坚定青年身体。张力：她的造型像能立刻被复印、分发、贴上墙。视觉证据：复印小志、短裙配军靴、手写标语、剪贴纸片、胶带、黑白复印质感和坚定直视。边界：避免写成普通摇滚粉丝。', defEn: 'First read: a Riot Grrrl zine maker tying DIY publishing to body styling. Styling entry: a Riot Grrrl zine maker tying DIY publishing to body styling. Motif: a firm youth body after photocopy, collage, and handwritten slogans enter clothing. Tension: her look seems ready to be copied, distributed, and taped to walls. Visual evidence: photocopied zines, skirt with combat boots, handwritten slogans, cut paper scraps, tape, black-and-white copy texture, and firm direct gaze. Boundary: avoid making a normal rock fan.', tags: ['riot_grrrl', 'zine', 'punk'] },
  { id: 'anarchist_patch_jacket', name: '无政府布章外套青年', nameEn: 'Anarchist Patch-Jacket Youth', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是用布章密度和防御姿态表达立场的无政府布章外套青年。造型入口：用布章密度和防御姿态表达立场的无政府布章外套青年。母题：政治穿搭直接进入衣服表面。张力：不要靠口号叙事解释，而让缝线、污渍和背部图案承担态度。视觉证据：满布章夹克、手写符号、旧靴子、磨损袖口、污渍、贴满观点的背部和不愿被靠近的站姿。边界：避免写成演讲活动人物。', defEn: 'First read: an anarchist patch-jacket youth expressing position through patch density and defensive posture. Styling entry: an anarchist patch-jacket youth expressing position through patch density and defensive posture. Motif: political dressing directly on clothing surface. Tension: to avoid slogan narrative and let stitching, stains, and back graphics carry attitude. Visual evidence: patch-covered jacket, handwritten symbols, old boots, worn cuffs, stains, a back covered in positions, and stance unwilling to be approached. Boundary: avoid making a rally speaker.', risk: 'medium', tags: ['anarchist', 'patch_jacket', 'punk'] },
  { id: 'goth_record_store_clerk', name: '哥特唱片店店员', nameEn: 'Goth Record-Store Clerk', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是用亚文化知识保持距离的哥特唱片店店员。造型入口：用亚文化知识保持距离的哥特唱片店店员。母题：黑色质地、唱片翻找和冷淡推荐表情组成的店内身体。张力：他不是舞台哥特，而是在零售日常里用知识筛选别人。视觉证据：黑唇、银饰、黑色针织、唱片袋、熟练翻唱片的手、冷眼神和干燥推荐表情。边界：避免写成吸血鬼或普通店员。', defEn: 'First read: a goth record-store clerk keeping distance through subcultural knowledge. Styling entry: a goth record-store clerk keeping distance through subcultural knowledge. Motif: an in-store body made of black texture, record flipping, and dry recommendation face. Tension: he is not stage goth but filters others through knowledge in retail daily life. Visual evidence: black lips, silver jewelry, black knitwear, record tote, fingers smoothly flipping records, cold eyes, and dry recommendation expression. Boundary: avoid making a vampire or generic clerk.', tags: ['goth', 'record_store', 'clerk'] },
  { id: 'soft_grunge_tumblr_girl', name: 'Soft Grunge Tumblr女孩', nameEn: 'Soft-Grunge Tumblr Girl', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是像刚从床和网络之间起身的Soft Grunge Tumblr女孩。造型入口：像刚从床和网络之间起身的Soft Grunge Tumblr女孩。母题：低饱和自拍、美丽疲惫和柔软脏感组成的网络身体。张力：脏感很轻、很灰，不是硬核破坏。视觉证据：褪色针织、黑色短裙、旧相机、凌乱发尾、低饱和脸、松散衣物和半醒姿态。边界：避免写成真正脏乱流浪或高级时装大片。', defEn: 'First read: a soft-grunge Tumblr girl who seems to have just risen from between bed and internet. Styling entry: a soft-grunge Tumblr girl who seems to have just risen from between bed and internet. Motif: a network body made from low-saturation selfie, pretty fatigue, and soft dirtiness. Tension: grime is light and gray, not hardcore destruction. Visual evidence: faded knit, black skirt, old camera, messy hair ends, low-saturation face, loose clothing, and half-awake posture. Boundary: avoid making real squalor or high-fashion editorial.', tags: ['soft_grunge', 'tumblr', 'girl'] },
  { id: 'alt_barista', name: '另类咖啡师', nameEn: 'Alt Barista', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是工作制服被私人符号改写的另类咖啡师。造型入口：工作制服被私人符号改写的另类咖啡师。母题：亚文化进入服务业日常后的身体。张力：他不是舞台人物，而是在围裙、卷袖和手冲器具之间露出纹身、鼻环和个人边界。视觉证据：纹身手臂、围裙、鼻环、卷起袖口、手冲器具、围裙口袋和熟练但疏离的服务姿态。边界：避免写成普通潮人顾客。', defEn: 'First read: an alt barista whose work uniform is rewritten by private signs. Styling entry: an alt barista whose work uniform is rewritten by private signs. Motif: subculture entering service labor daily life. Tension: he is not a stage figure, but reveals tattoos, nose ring, and personal boundary between apron, rolled cuffs, and pour-over tools. Visual evidence: tattooed arms, apron, nose ring, rolled cuffs, pour-over gear, apron pockets, and skilled but distant service posture. Boundary: avoid making a generic fashionable customer.', tags: ['alt', 'barista', 'tattoo'] },
  { id: 'queer_punk_poet', name: '酷儿朋克诗人', nameEn: 'Queer Punk Poet', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是把自我命名缝进旧西装和诗页里的酷儿朋克诗人。造型入口：把自我命名缝进旧西装和诗页里的酷儿朋克诗人。母题：脆弱与挑衅并存的地下朗读身体。张力：传统正装被剪短、弄皱、别上符号后，既像保护也像攻击。视觉证据：染色短发、旧西装、别针、手写诗页、锋利站姿、皱布料和不完全防御的眼神。边界：避免写成普通文艺诗人或舞台偶像。', defEn: 'First read: a queer punk poet sewing self-naming into old suit and poem pages. Styling entry: a queer punk poet sewing self-naming into old suit and poem pages. Motif: an underground reading body where vulnerability and provocation coexist. Tension: traditional tailoring, shortened, wrinkled, and pinned with signs, becomes both protection and attack. Visual evidence: dyed short hair, old suit, pins, handwritten poem pages, sharp stance, wrinkled fabric, and eyes not fully defended. Boundary: avoid making a generic literary poet or stage idol.', tags: ['queer_punk', 'poet', 'underground'] },
  { id: 'post_internet_sad_boy', name: '后互联网Sad Boy', nameEn: 'Post-Internet Sad Boy', group: 'I. 朋克 / Emo / 反主流青年', groupEn: 'I. Punk / Emo / Anti-Mainstream Youth', def: '第一识别是被屏幕生活压低肩膀、眼神和衣服颜色的后互联网Sad Boy。造型入口：被屏幕生活压低肩膀、眼神和衣服颜色的后互联网Sad Boy。母题：表情包式自嘲与真实疲惫混在一起的网络忧郁身体。张力：他像在开玩笑，但碎屏手机和自拍脸显示疲惫是真的。视觉证据：宽松帽衫、碎屏手机、耳机线、疲惫自拍脸、灰暗配色、塌肩和像刚发完动态的眼神。边界：避免写成长篇悲伤故事。', defEn: 'First read: a post-internet sad boy whose shoulders, gaze, and clothing color are lowered by screen life. Styling entry: a post-internet sad boy whose shoulders, gaze, and clothing color are lowered by screen life. Motif: an internet-melancholy body mixing meme-like self-mockery with real fatigue. Tension: he seems to joke, but the cracked phone and selfie face show tiredness is real. Visual evidence: oversized hoodie, cracked phone, earbud wires, tired selfie face, gray palette, slumped shoulders, and eyes like he just posted something. Boundary: avoid making a long tragic story.', ontologyLevel: 2, eras: contemporaryEras, tags: ['sad_boy', 'post_internet', 'meme'] },

  { id: 'glitchcore_streamer', name: 'Glitchcore主播', nameEn: 'Glitchcore Streamer', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是把故障感做进妆面、屏幕边框和姿态断裂里的Glitchcore主播。造型入口：把故障感做进妆面、屏幕边框和姿态断裂里的Glitchcore主播。母题：直播界面持续干扰身体形象。张力：画面可以卡顿、错位，但人物不能溶解成抽象噪声。视觉证据：RGB错位妆、耳机、直播灯、碎片贴纸、卡顿式表情、断裂手势和屏幕反光。边界：避免生成纯故障图案或真实机械身体。', defEn: 'First read: a glitchcore streamer putting glitch into makeup, screen border, and broken posture. Styling entry: a glitchcore streamer putting glitch into makeup, screen border, and broken posture. Motif: a body image continuously disturbed by streaming interface. Tension: the image may stutter and split while the person must not dissolve into abstract noise. Visual evidence: RGB-split makeup, headset, stream light, fragment stickers, stuttering expression, broken gestures, and screen reflection. Boundary: avoid generate pure glitch pattern or real mechanical body.', ontologyLevel: 3, eras: contemporaryEras, risk: 'medium', tags: ['glitchcore', 'streamer', 'digital'] },
  { id: 'vaporwave_mall_ghost', name: 'Vaporwave商场幽灵', nameEn: 'Vaporwave Mall Ghost', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是像被复古商场光和消费记忆褪色处理过的Vaporwave商场幽灵。造型入口：像被复古商场光和消费记忆褪色处理过的Vaporwave商场幽灵。母题：空旷、重复和低饱和消费感制造出的轻幽灵身体。张力：幽灵感来自褪色和空间感，不来自恐怖怪物。视觉证据：粉紫运动装、复古商场色光、雕像图案、低饱和脸、半透明消费感和像被空间吞轻的站姿。边界：避免生成鬼怪器官或惊悚表情。', defEn: 'First read: a vaporwave mall ghost faded by retro mall light and consumer memory. Styling entry: a vaporwave mall ghost faded by retro mall light and consumer memory. Motif: a lightly ghostly body produced by emptiness, repetition, and low-saturation consumer mood. Tension: ghostliness comes from fading and space, not horror-monster anatomy. Visual evidence: pink-purple sportswear, retro mall light, statue motifs, low-saturation face, translucent consumer feeling, and stance made light by space. Boundary: avoid generate ghost organs or horror expression.', ontologyLevel: 3, eras: ['modern', 'contemporary', 'timeless'], risk: 'medium', tags: ['vaporwave', 'mall', 'ghost'] },
  { id: 'liminal_space_teen', name: '阈限空间少年', nameEn: 'Liminal-Space Teen', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是被空走廊和不确定站位吞轻的阈限空间少年。造型入口：被空走廊和不确定站位吞轻的阈限空间少年。母题：空间比故事更强的网络不安感。张力：他不需要复杂背景，只要像不知道自己该不该出现在这里。视觉证据：校服外套、空走廊色温、模糊表情、过干净鞋底、停顿姿态和犹豫脚尖方向。边界：避免写成完整校园剧情或恐怖怪物。', defEn: 'First read: a liminal-space teen made light by empty corridors and uncertain placement. Styling entry: a liminal-space teen made light by empty corridors and uncertain placement. Motif: internet unease where space is stronger than story. Tension: he needs no complex background, only the feeling of not knowing whether he should be here. Visual evidence: school jacket, empty-corridor color temperature, blurred expression, too-clean soles, paused posture, and hesitant toe direction. Boundary: avoid making a full school plot or horror monster.', ontologyLevel: 3, eras: contemporaryEras, risk: 'medium', tags: ['liminal_space', 'teen', 'internet'] },
  { id: 'weirdcore_avatar_kid', name: 'Weirdcore头像青年', nameEn: 'Weirdcore Avatar Kid', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是像从Weirdcore头像里长出来的青年。造型入口：像从Weirdcore头像里长出来的青年。母题：不安可爱与低清图像符号合成的人形界面。张力：异常只能作为图案、贴纸和面部符号出现，人物仍要保持清楚人形。视觉证据：错位眼睛图案、低清印花、玩具色配饰、不安的可爱表情、头像式正面性和略微不对称的装饰。边界：避免变成真实多眼怪物。', defEn: 'First read: a youth who seems grown out of a weirdcore avatar. Styling entry: a youth who seems grown out of a weirdcore avatar. Motif: a humanoid interface made from uneasy cuteness and low-res image signs. Tension: anomaly may appear only as pattern, sticker, and facial sign while the figure stays clearly human. Visual evidence: displaced eye motifs, low-res prints, toy-colored accessories, uneasy cute expression, avatar-like frontality, and slightly mismatched decoration. Boundary: avoid turn into a real many-eyed monster.', ontologyLevel: 3, eras: contemporaryEras, risk: 'medium', tags: ['weirdcore', 'avatar', 'internet'] },
  { id: 'crypto_party_bro', name: 'Crypto派对青年', nameEn: 'Crypto Party Bro', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是把金融词汇、行情界面和派对社交穿成自信的Crypto派对青年。造型入口：把金融词汇、行情界面和派对社交穿成自信的Crypto派对青年。母题：投机泡沫里的社交身体。张力：衣服很贵、笑容很亮，但眼神和姿态有一种空洞轻浮。视觉证据：昂贵球鞋、派对腕带、手机行情界面、过亮笑容、展示屏幕的手势和像随时谈收益的身体角度。边界：避免写成真正金融精英。', defEn: 'First read: a crypto party bro wearing financial language, market screens, and party sociality as confidence. Styling entry: a crypto party bro wearing financial language, market screens, and party sociality as confidence. Motif: a social body inside speculation bubbles. Tension: clothes are expensive and smile is bright, yet eyes and posture feel hollow and shallow. Visual evidence: expensive sneakers, party wristband, market screen on phone, too-bright smile, gesture showing the screen, and body angle ready to talk gains. Boundary: avoid making a real finance elite.', risk: 'medium', tags: ['crypto', 'party', 'bro'] },
  { id: 'hacker_space_girl', name: '黑客空间女孩', nameEn: 'Hackerspace Girl', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是技术感落在手边工具和衣物磨损上的黑客空间女孩。造型入口：技术感落在手边工具和衣物磨损上的黑客空间女孩。母题：熬夜、旧设备和自制环境组成的技术身体。张力：她不需要赛博盔甲，焊锡痕迹和贴纸笔记本已经说明能力。视觉证据：旧笔记本、贴纸外壳、连帽衫、焊锡痕迹、熬夜眼神、工具线缆和靠近桌面的前倾姿态。边界：避免写成科幻战士或普通程序员头像。', defEn: 'First read: a hackerspace girl whose technical feeling lands in tools and worn clothing. Styling entry: a hackerspace girl whose technical feeling lands in tools and worn clothing. Motif: a technical body made from sleeplessness, old devices, and self-made environment. Tension: she needs no cyber armor because solder marks and sticker-covered laptop already show ability. Visual evidence: old laptop, stickered shell, hoodie, solder marks, sleepless eyes, tool cables, and forward posture near the desk. Boundary: avoid making a sci-fi warrior or generic programmer avatar.', ontologyLevel: 2, eras: contemporaryEras, tags: ['hackerspace', 'girl', 'laptop'] },
  { id: 'esports_substitute_player', name: '电竞替补选手', nameEn: 'Esports Substitute Player', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是装备完整但身体还在等待被叫到的电竞替补选手。造型入口：装备完整但身体还在等待被叫到的电竞替补选手。母题：职业化与边缘位置并存的年轻身体。张力：队服、键盘包和眼镜都很正式，坐姿却始终没有完全安稳。视觉证据：队服外套、眼镜、键盘包、紧张手指、半坐半起的姿态、备用席距离和等待上场的眼神。边界：避免写成冠军明星选手。', defEn: 'First read: an esports substitute player with complete equipment but a body still waiting to be called. Styling entry: an esports substitute player with complete equipment but a body still waiting to be called. Motif: a young body where professionalism coexists with marginal status. Tension: team jacket, keyboard bag, and glasses are official, yet posture never fully settles. Visual evidence: team jacket, glasses, keyboard bag, nervous fingers, half-seated posture, substitute-bench distance, and eyes waiting to play. Boundary: avoid making a champion star player.', eras: contemporaryEras, tags: ['esports', 'substitute', 'player'] },
  { id: 'vtuber_fan_shrine_keeper', name: 'VTuber应援神龛守护者', nameEn: 'VTuber Fan-Shrine Keeper', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是被虚拟偶像周边包围成私人展示台的VTuber应援神龛守护者。造型入口：被虚拟偶像周边包围成私人展示台的VTuber应援神龛守护者。母题：粉丝身体被屏幕光、立牌和徽章布置成小型仪式空间。张力：这不是宗教故事，而是房间物件组织出的忠诚。视觉证据：应援灯、立牌、屏幕光、徽章挂带、小心摆放周边的手和被物件围住的坐姿。边界：避免写成真正祭司或偶像本人。', defEn: 'First read: a VTuber fan-shrine keeper surrounded by virtual idol merch into a private display altar. Styling entry: a VTuber fan-shrine keeper surrounded by virtual idol merch into a private display altar. Motif: a fan body arranged into a small ritual space by screen glow, standees, and badges. Tension: this is not a religion story but loyalty organized by room objects. Visual evidence: light sticks, standees, screen glow, badge lanyard, careful hands arranging merch, and seated posture surrounded by objects. Boundary: avoid making a real priest or the idol themselves.', ontologyLevel: 2, eras: contemporaryEras, tags: ['vtuber', 'fan', 'shrine'] },
  { id: 'ai_filter_influencer', name: 'AI滤镜网红', nameEn: 'AI-Filter Influencer', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是现实身体边缘被滤镜轻微校正到不协调的AI滤镜网红。造型入口：现实身体边缘被滤镜轻微校正到不协调的AI滤镜网红。母题：算法美颜制造出的过度顺滑公众形象。张力：异常必须细微：皮肤太顺、眼睛太亮、姿态像被软件修正。视觉证据：过度平滑面部、虚拟妆容、手机支架、环形灯、轻微不匹配的身体边缘和完美到发假的自拍姿态。边界：避免变成机器人或纯CG模特。', defEn: 'First read: an AI-filter influencer whose real body edges are subtly corrected into mismatch. Styling entry: an AI-filter influencer whose real body edges are subtly corrected into mismatch. Motif: an over-smoothed public image manufactured by algorithmic beauty. Tension: anomaly must be subtle: skin too smooth, eyes too bright, posture software-corrected. Visual evidence: over-smoothed face, virtual makeup, phone stand, ring light, slight mismatch at body edges, and a selfie posture perfect enough to feel fake. Boundary: avoid turn into a robot or pure CG model.', ontologyLevel: 3, eras: contemporaryEras, risk: 'medium', tags: ['ai_filter', 'influencer', 'virtual_makeup'] },
  { id: 'digital_ritual_chatroom_admin', name: '数字仪式聊天室管理员', nameEn: 'Digital-Ritual Chatroom Admin', group: 'J. 网络 / 故障 / 数字亚文化', groupEn: 'J. Internet / Glitch / Digital Subculture', def: '第一识别是用规则公告、头像徽章和冷静管理姿态制造神秘感的数字仪式聊天室管理员。造型入口：用规则公告、头像徽章和冷静管理姿态制造神秘感的数字仪式聊天室管理员。母题：网络群体秩序被仪式化后的管理身体。张力：神秘感落在UI符号和静止眼神上，不直接变成法师。视觉证据：暗色界面、符号头像徽章、耳机、规则公告截图、服装小标记和冷静审视成员的姿态。边界：避免写成魔法祭司或企业管理员。', defEn: 'First read: a digital-ritual chatroom admin creating mystery through rule announcements, avatar badges, and calm moderation posture. Styling entry: a digital-ritual chatroom admin creating mystery through rule announcements, avatar badges, and calm moderation posture. Motif: a management body after online group order becomes ritualized. Tension: mystery lands in UI signs and still eyes, not a literal mage. Visual evidence: dark interface, symbolic avatar badge, headset, rule-announcement screenshots, small clothing marks, and calm posture inspecting members. Boundary: avoid making a magic priest or corporate admin.', ontologyLevel: 3, eras: contemporaryEras, risk: 'medium', tags: ['digital_ritual', 'chatroom', 'admin'] }
];

